// ── Actor context ────────────────────────────────────────────

type StagedInvoiceLineInput = {
  line_type?: 'product' | 'text'
  description?: string
  quantity: number
  unit?: string
  unit_price?: number
  /** Line discount 0-100 (rabatt i procent); totals are computed net of it. */
  discount_percent?: number
  vat_rate?: number
  article_id?: string
  revenue_account?: string | null
  // Deduction claim fields (CreateInvoiceItemSchema parity: ROT, RUT, grön
  // teknik). The housing columns are property identifiers, never the
  // personnummer: the stored personnummer exists only as ciphertext and
  // never crosses the MCP surface.
  deduction_type?: DeductionType | null
  labor_hours?: number | null
  work_type?: string | null
  housing_designation?: string | null
  apartment_number?: string | null
  brf_org_number?: string | null
  // Periodisering (förutbetald intäkt): pass-through to the builder.
  accrual_period_start?: string | null
  accrual_period_end?: string | null
  accrual_balance_account?: string | null
  dimensions?: unknown
}

/**
 * gnubok_create_invoice's line schema. The staging refusal of unknown line
 * keys reads its property list plus the deduction and periodisering fields:
 * the top-level arg guard never sees inside items, so a misnamed or
 * unsupported line field used to be staged and then dropped at approval
 * without a word. Those fields are accepted but not repeated here, where
 * every property costs tools/list budget; gnubok_update_invoice declares
 * them and the refusal names them all.
 */
const CREATE_INVOICE_ITEM_SCHEMA = {
  type: 'object',
  properties: {
    description: { type: 'string' },
    quantity: { type: 'number' },
    unit: { type: 'string', description: 'st, tim, dag, mån' },
    unit_price: { type: 'number', description: 'Price per unit excl. VAT' },
    discount_percent: { type: 'number', description: 'Line discount 0-100 (rabatt); line total and VAT computed net of it' },
    vat_rate: { type: 'number', description: 'VAT rate 0-100 (optional override)' },
    article_id: {
      type: 'string',
      description: 'Optional article UUID from gnubok_list_articles. Prefills description, unit, unit_price, revenue account and, only when compatible with the customer VAT rules, vat_rate. Values set on the line win.',
    },
    line_type: { type: 'string', enum: ['product', 'text'], description: 'text = free-text row: no amounts, never books.' },
    revenue_account: { type: ['string', 'null'], description: 'BAS class 1-3 posting account; class 1-2 only at 0 % VAT.' },
    dimensions: {
      type: 'object',
      additionalProperties: { type: 'string' },
      description: 'Dims bag {sie_dim_no: kod eller namn}, e.g. {"6":"P001"}. Wins per key over default_dimensions.',
    },
  },
  required: ['quantity'],
}

const CREATE_INVOICE_ITEM_KEYS: ReadonlySet<string> = new Set([
  ...Object.keys(CREATE_INVOICE_ITEM_SCHEMA.properties),
  // ROT/RUT/grön teknik claim fields; the personnummer comes from the
  // customer card and never crosses MCP.
  'deduction_type',
  'labor_hours',
  'work_type',
  'housing_designation',
  'apartment_number',
  'brf_org_number',
  // Periodisering (förutbetald intäkt).
  'accrual_period_start',
  'accrual_period_end',
  'accrual_balance_account',
])

type ResolvedInvoiceLine = StagedInvoiceLineInput & {
  description: string
  unit: string
  unit_price: number
}

type InvoiceLineArticle = {
  id: string
  name: string
  name_en: string | null
  unit: string | null
  price_excl_vat: number | null
  vat_rate: number | null
  revenue_account: string | null
  currency: string | null
  active: boolean
}

/**
 * Article prefill for one staged invoice line (web line picker parity,
 * InvoiceEditor's applyArticle): the line's own values win and the article
 * fills whatever the agent left out. The article's VAT rate is adopted ONLY
 * when it is in the customer's DEFAULT rate set (adoptableVatRates, empty for
 * a customer locked to a single rate): an article's stored rate is its
 * domestic rate, and adopting it against the wider permitted set would
 * silently put Swedish VAT on a reverse-charge or export invoice.
 */
function resolveInvoiceLineFromArticle(
  item: StagedInvoiceLineInput,
  article: InvoiceLineArticle | undefined,
  currency: string,
  adoptableVatRates: ReadonlySet<number>,
  index: number,
  language: DocumentLanguage,
): ResolvedInvoiceLine {
  const lineNo = index + 1
  // Free-text / spacer rows (web parity, CreateInvoiceItemSchema): no
  // amounts, never book, exempt from the quantity/description/unit/price
  // gates. Normalized to the exact zeroed shape build-invoice-write stores so
  // a gnubok_get_invoice line passes back verbatim.
  if (item.line_type === 'text') {
    if (item.article_id) {
      throw new Error(`Item ${lineNo}: a text row cannot carry article_id (drop line_type or article_id)`)
    }
    return {
      ...item,
      description: item.description ?? '',
      quantity: 0,
      unit: '',
      unit_price: 0,
      discount_percent: 0,
      vat_rate: 0,
    }
  }
  // The web's quantity rule (lib/invoices/line-quantity.ts): zero and
  // negative are valid, except on a skattereduktion row.
  const quantityIssue = lineQuantityIssue(item)
  if (quantityIssue) {
    throw badArgument(`items.${index}.quantity`, `Item ${lineNo}: ${LINE_QUANTITY_MESSAGES[quantityIssue]}`)
  }
  // Strict typeof: a host that skips inputSchema validation could send a
  // string, which JS comparisons would coerce past a bare range check while
  // hasLineDiscount (typeof === 'number') then ignores it in the totals.
  if (
    item.discount_percent != null &&
    (typeof item.discount_percent !== 'number' ||
      !(item.discount_percent >= 0 && item.discount_percent <= 100))
  ) {
    throw badArgument(`items.${index}.discount_percent`, `Item ${lineNo}: discount_percent must be a number between 0 and 100`)
  }
  if (item.article_id && !article) {
    throw new Error(`Item ${lineNo}: article ${item.article_id} not found in this company. Use gnubok_list_articles to find valid IDs.`)
  }
  if (article && !article.active) {
    throw new Error(`Item ${lineNo}: article "${article.name}" is deactivated. Reactivate it with gnubok_update_article (active: true) or drop article_id.`)
  }
  // The English benämning for an English-language customer (crm#1084).
  const description = item.description?.trim() || (article ? articleLineName(article, language) : undefined)
  if (!description) throw badArgument(`items.${index}.description`, `Item ${lineNo}: description is required (or set article_id)`)
  const unit = item.unit?.trim() || (article ? article.unit || 'st' : undefined)
  if (!unit) throw badArgument(`items.${index}.unit`, `Item ${lineNo}: unit is required (st, tim, dag)`)
  let unitPrice = item.unit_price
  if (unitPrice == null && article) {
    if (article.price_excl_vat == null) {
      throw new Error(`Item ${lineNo}: article "${article.name}" has no price; pass unit_price explicitly.`)
    }
    if (article.currency && article.currency !== currency) {
      throw new Error(
        `Item ${lineNo}: article "${article.name}" is priced in ${article.currency} but the invoice is in ${currency}. ` +
        `Set the invoice currency to ${article.currency} or pass unit_price explicitly.`
      )
    }
    unitPrice = article.price_excl_vat
  }
  if (unitPrice == null) throw badArgument(`items.${index}.unit_price`, `Item ${lineNo}: unit_price is required (or set article_id)`)
  return {
    ...item,
    description,
    unit,
    unit_price: unitPrice,
    ...(item.vat_rate == null && article?.vat_rate != null && adoptableVatRates.has(article.vat_rate)
      ? { vat_rate: article.vat_rate }
      : {}),
    ...(item.revenue_account == null && article?.revenue_account ? { revenue_account: article.revenue_account } : {}),
  }
}

export interface ActorContext {
  // 'anonymous': a client that has not connected an account yet (lazy
  // authentication, issue #1814). Only PUBLIC_TOOLS ever run under it.
  type: 'user' | 'api_key' | 'mcp_oauth' | 'cron' | 'anonymous'
  id?: string
  label?: string
  /**
   * Stable agent-session identifier from the `Mcp-Session-Id` JSON-RPC header
   * when present, otherwise null. Used to correlate `mcp.tool_called`,
   * `mcp.workflow_started`, `mcp.next_hint_followed`, etc. events across a
   * single agent conversation. Not used for auth.
   */
  sessionId?: string | null
  /**
   * Approval authority for this key in SEK: the largest amount it may commit
   * with no human in the loop, or null/undefined for unlimited (the default,
   * and what every key created before this column existed has).
   *
   * Only meaningful for `type: 'api_key'`. Read once at auth time so the
   * ceiling cannot drift mid-request.
   */
  unattendedCommitLimit?: number | null
  /**
   * Distribution-channel marker from `X-Accounted-Client`, the legacy
   * `X-Gnubok-Client`, or the `client` query param (e.g. 'openclaw'); without
   * one, a label derived from the OAuth provider, the MCP clientInfo name or
   * the User-Agent (client-label.ts). Telemetry-only: same trust level as
   * Mcp-Session-Id, never used for auth or behavior.
   */
  client?: string | null
  /** Sanitized raw client name when the derived label is 'other'. Telemetry-only. */
  clientName?: string | null
  /** Which fallback produced `client`; null when it came from the marker. Telemetry-only. */
  clientSource?: ClientSource | null
  /**
   * The provider the OAuth sign-in minted this key for (api_keys.client),
   * decided server-side from the validated redirect URI; null for any other
   * key. Unlike `client` an authorization input, recorded on approvals.
   */
  oauthProvider?: string | null
  /**
   * This request comes through a connection with Accounted's approval view
   * (approvalViewFor in view-approval.ts): an authorization input for the
   * view's own approve door and its tokens.
   */
  approvalView?: boolean
  /**
   * Per-key company allowlist (validateApiKey().allowedCompanyIds): null
   * when the key reaches every membership. An authorization input, not
   * telemetry: the tools that enumerate or resolve companies intersect with
   * it. Only meaningful for `type: 'api_key'`.
   */
  allowedCompanyIds?: string[] | null
  /**
   * Companies in the allowlist where this key may only read
   * (validateApiKey().readOnlyCompanyIds): null when there are none. An
   * authorization input: every write gate (assertMcpCompanyWriteAccess)
   * refuses write-scoped tools there. Only meaningful for `type: 'api_key'`.
   */
  readOnlyCompanyIds?: string[] | null
  /**
   * The company this connection is pinned to (`?company=<uuid>` on the MCP
   * URL), or null. Also the key default for the request. Tools that
   * enumerate companies list only this one under a pin.
   */
  pinnedCompanyId?: string | null
  /**
   * True when the key was minted by the OAuth sign-in (a connector such as
   * claude.ai or ChatGPT), false or absent for a key a person created:
   * credentialActor decides it, here and on every other door.
   * Only meaningful for `type: 'api_key'`.
   */
  oauthKey?: boolean
  /**
   * The service account the key belongs to (lib/service-accounts), or
   * null/absent for a person's key. The connection keeps `type: 'api_key'`
   * for every access decision (the key acts as the account's sponsor, in the
   * account's company only); the records it writes name the actor
   * 'service_account' with the account's name as the label.
   */
  serviceAccountId?: string | null
  /**
   * Whether the key holds pending_operations:approve, read at auth time with
   * the other key facts. A staging answer uses it to say for certain whether
   * the agent approves here or the person approves in the app; undefined (an
   * in-app actor, a test double) keeps the conditional wording.
   * Only meaningful for `type: 'api_key'`.
   */
  canApprove?: boolean
  /**
   * The agent identity the key belongs to (validateApiKey().agentIdentityId),
   * when known. Attribution only: the permission shadow names the agent in
   * what it logs. Only meaningful for `type: 'api_key'`.
   */
  agentIdentityId?: string | null
}

// ── JSON-RPC types ───────────────────────────────────────────

interface JsonRpcRequest {
  jsonrpc: '2.0'
  id?: string | number
  method: string
  params?: Record<string, unknown>
}

interface JsonRpcResponse {
  jsonrpc: '2.0'
  id: string | number | null
  result?: unknown
  error?: { code: number; message: string; data?: unknown }
}

// ── MCP Tool definition ──────────────────────────────────────

export interface McpToolAnnotations {
  effect: McpToolEffect
  readOnlyHint?: boolean
  destructiveHint?: boolean
  idempotentHint?: boolean
  openWorldHint?: boolean
}

// Shared annotation sets. tools/list serialises `annotations` as-is, so a
// shared frozen object emits exactly the JSON an inline literal did; nothing
// mutates a tool's annotations after registration. Tools whose hints need
// a per-tool explanation keep an inline block with comments.
// An own item's id as create_skill returned it, or its own/<id> slug.
const OwnSkillIdSchema = z.string().trim().transform((id) => id.replace(/^own\//, '')).pipe(z.string().uuid())
// delete: true takes only the id; anything else would be ignored, so it is refused.
const DeleteSkillArgsSchema = z.object({ company_skill_id: OwnSkillIdSchema, delete: z.literal(true) }).strict()
const CreateSkillArgsSchema = z.object({
  // Set: replace that own item's content (same id) instead of saving a new one.
  company_skill_id: OwnSkillIdSchema.optional(),
  delete: z.literal(false).optional(),
  // What the user makes: a flow is steps, knowledge and an analysis are text.
  kind: z.enum(['workflow', 'rules', 'analysis']).default('workflow'),
  name: z.string().min(1).max(120),
  description: z.string().min(1).max(500),
  steps: z.array(z.string().min(1).max(200)).max(12).default([]),
  text: z.string().max(20000).default(''),
  rules: z.array(z.string().min(1).max(200)).max(10).default([]),
  told: z.string().max(4000).default(''),
  language: z.enum(['sv', 'en']).default('sv'),
}).strict().refine((input) => input.kind === 'workflow' ? input.steps.length > 0 : input.text.trim().length > 0, {
  message: 'A workflow needs steps; knowledge and an analysis need text',
})

/**
 * Recurring schedule lines may link only this company's articles (the commit
 * executor checks again). Refused at staging so the agent learns it before
 * anyone approves.
 */
async function assertRecurringArticlesOwned(
  supabase: SupabaseClient,
  companyId: string,
  items: ReadonlyArray<{ line_type?: string | null; article_id?: string | null }>,
): Promise<void> {
  const { invalidArticleIds, error } = await findForeignRecurringArticleIds(supabase, companyId, items)
  if (error) throw dbError(error)
  if (invalidArticleIds.length > 0) {
    throw badArgument('items', `${RECURRING_ARTICLE_INVALID_MESSAGE} (${invalidArticleIds.join(', ')}). Use gnubok_list_articles.`)
  }
}

/**
 * The company's own private item an agent may replace or delete (crm#1506).
 * Never a catalog row (atom_id), never a firm-wide item (team_id: the firm's
 * owners change those in Accounted) and never one shared with the community,
 * whose text is frozen for review until the user withdraws it.
 */
async function requireOwnPrivateSkill(supabase: SupabaseClient, companyId: string, id: string): Promise<void> {
  const { data, error } = await supabase
    .from('company_skills')
    .select('id, atom_id, share_status')
    .eq('id', id)
    .eq('company_id', companyId)
    .maybeSingle()
  if (error) throw error
  if (!data || data.atom_id) {
    throw codedRefusal('NOT_FOUND', `Own item not found: own/${id} is not an own item of this company. gnubok_list_skills lists the added ones (tier own).`)
  }
  if (data.share_status !== 'private') {
    throw codedRefusal('CONFLICT', `own/${id} is shared with the community, so its text is frozen. The user withdraws the sharing in Accounted first.`)
  }
}

const ANNOTATIONS_READ_ONLY = annotationsForEffect('read_only', {
  idempotentHint: true,
  openWorldHint: false,
}) satisfies McpToolAnnotations
/** A verifikat a supplier invoice points at, as gnubok_get_supplier_invoice returns it. */
const SUPPLIER_INVOICE_VOUCHER_REF_SCHEMA = {
  type: ['object', 'null'],
  description: 'null when not booked. voucher is null while a draft; labels repeat per fiscal year, entry_date tells them apart',
  properties: {
    journal_entry_id: { type: 'string' },
    voucher: { type: ['string', 'null'] },
    entry_date: { type: 'string' },
    status: { type: 'string' },
  },
} as const
// dry_run and idempotency_key: the staging arguments every write tool takes
// (stagingOptions turns them into staging options).
const STAGING_ARGS_PROPERTIES = {
  dry_run: {
    type: 'boolean',
    description: 'Preview only: nothing is staged or written.',
  },
  idempotency_key: IDEMPOTENCY_KEY_PROPERTY,
} as const

/** Stages a pending operation or writes once; retries are not idempotent. */
const ANNOTATIONS_STAGED_WRITE = annotationsForEffect('additive', {
  idempotentHint: false,
  openWorldHint: false,
}) satisfies McpToolAnnotations
const ANNOTATIONS_IDEMPOTENT_WRITE = annotationsForEffect('additive', {
  idempotentHint: true,
  openWorldHint: false,
}) satisfies McpToolAnnotations
const ANNOTATIONS_DESTRUCTIVE_WRITE = annotationsForEffect('destructive', {
  idempotentHint: false,
  openWorldHint: false,
}) satisfies McpToolAnnotations
const ANNOTATIONS_DESTRUCTIVE_IDEMPOTENT_WRITE = annotationsForEffect('destructive', {
  idempotentHint: true,
  openWorldHint: false,
}) satisfies McpToolAnnotations
/** Read-only tools that call an external system (Skatteverket, Riksbanken). */
const ANNOTATIONS_READ_ONLY_OPEN_WORLD = annotationsForEffect('read_only', {
  idempotentHint: true,
  openWorldHint: true,
}) satisfies McpToolAnnotations
/** Writes that also reach an external system. */
const ANNOTATIONS_WRITE_OPEN_WORLD = annotationsForEffect('additive', {
  idempotentHint: false,
  openWorldHint: true,
}) satisfies McpToolAnnotations

/**
 * A domain failure carrying a structured-errors registry code, so the dispatch
 * envelope (toToolError → getStructuredError) resolves the registry entry
 * instead of UNKNOWN_ERROR. The Swedish registry message is the thrown text.
 */
function registryError(code: string): Error {
  return Object.assign(new Error(getErrorEntry(code)?.message_sv ?? code), { code })
}

/** A payment_account that is not one of the company's enabled cash accounts, with the ones that are. */
function paymentAccountRefusal(details: Record<string, unknown>): Error {
  const available = (details.available_payment_accounts as string[] | undefined) ?? []
  return codedRefusal(
    'INVOICE_PAID_PAYMENT_ACCOUNT_INVALID',
    `gnubok_mark_invoice_as_paid: payment_account ${String(details.payment_account)} is not one of the company's enabled cash accounts (${String(details.reason)}). ` +
      (available.length > 0 ? `It can be: ${available.join(', ')}.` : 'The company has no enabled 19xx cash account.'),
    { description: 'Name one of the listed accounts (gnubok_list_cash_accounts shows them), or leave payment_account out.', tool: 'gnubok_list_cash_accounts' },
  )
}

/** A refused credit note refund (lib/invoices/refund-credit-note.ts) as the error the agent reads. */
function creditNoteRefundRefusal(failure: Extract<RefundCreditNoteResult, { ok: false }>): Error {
  if (failure.code === 'BOOKKEEPING_ERROR') return failure.error instanceof Error ? failure.error : new Error(String(failure.error))
  if (failure.code === 'DB_ERROR') return dbError(failure.error)
  const { code, message } = describeRefundFailure(failure)
  return codedRefusal(code, `gnubok_mark_invoice_as_paid: ${message}`)
}

/**
 * The way out of a run in review that needs a calculation: only a draft
 * calculates, and an input written during review leaves the run stale.
 */
const REVIEW_RUN_EXIT = 'Send it back to draft with gnubok_revert_salary_run, approve that, then run gnubok_calculate_salary_run.'
const reviewRunExit = (salaryRunId: string) => ({
  description: REVIEW_RUN_EXIT,
  tool: 'gnubok_revert_salary_run',
  args: { salary_run_id: salaryRunId },
})

/** SALARY_RUN_NOT_FOUND naming the id the agent sent. */
function salaryRunNotFound(salaryRunId: string): Error {
  return codedRefusal('SALARY_RUN_NOT_FOUND', `Salary run not found: no run with id ${salaryRunId} in this company.`)
}

/**
 * The run a `.maybeSingle()` salary_runs lookup found, or the refusal an agent
 * can act on. A malformed id (22P02) is a miss as well: no run can have it.
 * Any other database failure keeps its SQLSTATE, so a timeout stays transient.
 */
function salaryRunOrThrow<T>(
  result: { data: T | null; error: { code?: string | null; message?: string | null } | null },
  salaryRunId: string,
): NonNullable<T> {
  if (result.error && result.error.code !== '22P02') throw dbError(result.error)
  if (!result.data) throw salaryRunNotFound(salaryRunId)
  return result.data as NonNullable<T>
}

/**
 * A refused employee command (lib/salary/employee-commands.ts) as the agent
 * reads it: every issue as a field refusal, the EF-owner rule with the way
 * out in English; any other code as serviceRefusal phrases it.
 */
function employeeCommandRefusal(
  context: string,
  failure: { code: string; details?: Record<string, unknown> },
): Error {
  const issues = failure.details?.issues as Array<{ field: string; message: string }> | undefined
  if (failure.code !== 'VALIDATION_ERROR' || !issues?.length) return serviceRefusal(context, failure)
  return fieldValidationError(
    context,
    issues.map((issue) => ({
      field: issue.field,
      en:
        issue.field === 'employment_type'
          ? 'an enskild firma cannot employ its owner or board: the owner takes eget uttag (account 2013), not salary; use "employee" for hired staff'
          : issue.message,
      sv: issue.message,
    })),
  )
}

/** A missing salary_run_id: hosts do not always enforce inputSchema `required`. */
function salaryRunIdRequired(): Error {
  return fieldValidationError('Invalid arguments', [
    { field: 'salary_run_id', en: 'is required', sv: 'Obligatoriskt fält saknas: ange lönekörningens id.' },
  ])
}

/**
 * The soft-duplicate refusal for gnubok_match_transaction_to_invoice, coded
 * like the dashboard route: MATCH_INVOICE_POSSIBLE_DUPLICATE without force,
 * MATCH_INVOICE_FORCE_CANDIDATE_MISMATCH when force names a stale or absent
 * candidate.
 */
function duplicateCandidateRefusal(
  outcome: Extract<DuplicateCandidateOutcome, { status: 'blocked' | 'mismatch' }>,
): Error {
  if (outcome.status === 'mismatch') {
    return Object.assign(
      new Error(
        `force=true avvisad: expected_journal_entry_id ${outcome.expected_journal_entry_id ?? '(saknas)'} är inte den verifikation dubblettkontrollen hittar just nu ` +
          `(${outcome.detected_journal_entry_id ?? 'ingen dubblett hittad: anropa igen utan force'}).`,
      ),
      { code: 'MATCH_INVOICE_FORCE_CANDIDATE_MISMATCH' },
    )
  }
  const c = outcome.candidate
  const amount = c.amount_verified
    ? `${c.amount.toLocaleString('sv-SE', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} kr`
    : 'belopp ej verifierat: raden saknar SEK-värde'
  return Object.assign(
    new Error(
      `Möjlig dubblettbokföring: verifikat ${c.voucher_label} (${c.entry_date}, konto ${c.bank_account_number}, ${amount}) ser redan ut att bokföra den här betalningen. ` +
        `Koppla transaktionen till den i stället: gnubok_link_transaction_to_journal_entry (journal_entry_id="${c.journal_entry_id}", invoice_id för att markera fakturan betald samtidigt). ` +
        `Endast om det verkligen är en separat betalning: anropa igen med force=true och expected_journal_entry_id="${c.journal_entry_id}".`,
    ),
    { code: 'MATCH_INVOICE_POSSIBLE_DUPLICATE' },
  )
}

/**
 * A match refused on the row or the invoice alone, at staging as at approval
 * (refuseCustomerBankMatch). A booked row's English says which tool opens it.
 */
function customerMatchRefusal(refusal: CustomerBankMatchRefusal): Error {
  const booked = bankRowAlreadyBookedMessages(refusal.code, refusal.details)
  return booked ? codedRefusal(refusal.code, booked.message_en) : registryError(refusal.code)
}

/**
 * The stage-time overpayment refusal for a transaction-to-invoice match,
 * coded MATCH_AMOUNT_EXCEEDS_REMAINING like the approval that would otherwise
 * reject the staged op (crm#253). The registry's Swedish sentence is generic,
 * so message_en carries what the agent needs: the three amounts and the
 * routes that book an overpayment today. Where the excess belongs (another
 * invoice, a liability to the customer, a write-off) is the user's call, so
 * the agent is told to ask rather than pick an account. Keep the English free
 * of Swedish letters: a message that reads as Swedish (isSwedishUserMessage)
 * would replace the registry's message_sv instead of riding message_en.
 *
 * A pure-SEK match books the excess in the same verifikat once the user names
 * the account (overpayment_account: 2420 any amount, 3740 under its cap).
 * A cross-currency match cannot, so it settles the invoice and books the excess
 * separately. That route depends on the invoice: a sent or
 * overdue invoice can be marked paid for exactly its remaining amount (any
 * accounting method), with the excess as its own two-line verifikat and the
 * bank row split across both; a partially paid one cannot, so it takes one
 * verifikat linked through its 1510 credit, which only faktureringsmetoden
 * reads (kontantmetoden matches the bank debit, which here exceeds the
 * remaining amount).
 */
function overpaymentRefusal(
  outcome: Extract<MatchPaymentPlanResult, { code: 'MATCH_AMOUNT_EXCEEDS_REMAINING' }>,
  ctx: { invoiceStatus: string; transactionDate: string },
): Error {
  const amount = (n: number) => `${AGENT_AMOUNT_FORMAT.format(n)} ${outcome.currency}`
  const { transaction_amount: paid, remaining_amount: remaining, excess } = outcome.details
  const band = outcome.absorbsOre
    ? `only a difference under ${amount(ORE_ROUNDING_SETTLEMENT_MAX)} is settled automatically as a rounding difference on 3740`
    : 'a cross-currency match cannot settle more than the remaining amount'
  const roundingFits = excess < OVERPAYMENT_ROUNDING_MAX
  const separately = outcome.absorbsOre
    ? `call gnubok_match_transaction_to_invoice with overpayment_account: "${CUSTOMER_ADVANCE_ACCOUNT}" books the excess as an advance from the customer ` +
      '(a liability to refund or offset against a later invoice)' +
      (roundingFits
        ? `, "3740" as a rounding difference (only under ${amount(OVERPAYMENT_ROUNDING_MAX)}, when the customer rounded the payment up)`
        : '') +
      `; the invoice then settles for exactly ${amount(remaining)} in the same verifikat`
    : ctx.invoiceStatus === 'partially_paid'
      ? `book one verifikat with gnubok_create_voucher (debit the bank account ${amount(paid)}, credit 1510 ${amount(remaining)}, ` +
        `credit the account the user chose ${amount(excess)}), settle the invoice from it with gnubok_link_invoice_to_voucher ` +
        `(faktureringsmetoden only), and link the bank row to it with gnubok_reconcile_match`
      : `settle this invoice with gnubok_mark_invoice_as_paid (payment_date ${ctx.transactionDate}; it books exactly ${amount(remaining)}), ` +
        `book the ${amount(excess)} excess with gnubok_create_voucher (debit the bank account, credit the account the user chose), ` +
        `then link the bank row to both verifikat with one gnubok_reconcile_match pair (allocations ${amount(remaining)} and ${amount(excess)})`
  return codedRefusal(
    'MATCH_AMOUNT_EXCEEDS_REMAINING',
    `Not staged: the transaction (${amount(paid)}) exceeds the invoice's remaining amount (${amount(remaining)}) by ${amount(excess)}. ` +
      `A match settles at most the remaining amount and ${band}, so approval would reject this match. ` +
      'Ask the user where the excess belongs (another open invoice, a liability to the customer to refund or offset, or a rounding difference), then: ' +
      `if it pays other open invoices from the same customer, allocate the transaction across them with gnubok_match_batch_allocate ` +
      `(allocations summing to ${amount(paid)}); otherwise ${separately}.`,
    {
      description:
        'Do not retry this match unchanged: it fails until the amounts change. Ask the user where the excess belongs, then use a route the message names: gnubok_match_batch_allocate when it pays other invoices, otherwise (SEK) the same match with overpayment_account, or settle the invoice and book the excess as its own verifikat.',
    },
  )
}

/**
 * overpayment_account "3740" named for an excess at or above
 * OVERPAYMENT_ROUNDING_MAX: that is the customer's money, not rounding, so
 * only 2420 (or another route) can take it.
 */
function roundingCapRefusal(
  outcome: Extract<MatchPaymentPlanResult, { code: 'MATCH_OVERPAYMENT_ROUNDING_CAP' }>,
): Error {
  const amount = (n: number) => `${AGENT_AMOUNT_FORMAT.format(n)} ${outcome.currency}`
  return codedRefusal(
    'MATCH_OVERPAYMENT_ROUNDING_CAP',
    `Not staged: the excess (${amount(outcome.details.excess)}) is ${amount(OVERPAYMENT_ROUNDING_MAX)} or more, and 3740 takes only a rounding difference under that. ` +
      `Ask the user, then call gnubok_match_transaction_to_invoice again with overpayment_account: "${CUSTOMER_ADVANCE_ACCOUNT}" (an advance from the customer, to refund or offset against a later invoice), ` +
      'or allocate the transaction across other open invoices with gnubok_match_batch_allocate.',
    {
      description: `Do not retry with 3740: call again with overpayment_account "${CUSTOMER_ADVANCE_ACCOUNT}" once the user agrees, or use gnubok_match_batch_allocate.`,
    },
  )
}

/**
 * fee_account named for a shortfall that cannot be a payment provider's fee:
 * a cross-currency match, or a gap of PAYMENT_FEE_MAX_PERCENT or more of the
 * remaining amount (crm#1364). That is a partial payment, so it stays one.
 */
function paymentFeeRefusal(
  outcome: Extract<MatchPaymentPlanResult, { code: 'MATCH_PAYMENT_FEE_NOT_ALLOWED' }>,
): Error {
  const amount = (n: number) => `${AGENT_AMOUNT_FORMAT.format(n)} ${outcome.currency}`
  const { transaction_amount: paid, remaining_amount: remaining, shortfall, reason } = outcome.details
  const why =
    reason === 'currency'
      ? 'a fee is booked only when the transaction and the invoice are both in SEK'
      : `a fee is under ${PAYMENT_FEE_MAX_PERCENT}% of the remaining amount, so a gap that size is a partial payment`
  return codedRefusal(
    'MATCH_PAYMENT_FEE_NOT_ALLOWED',
    `Not staged: the transaction (${amount(paid)}) is ${amount(shortfall)} short of the invoice's remaining amount (${amount(remaining)}) and ${why}. ` +
      'Call again without fee_account to book it as a partial payment, or check the payout with the user.',
    { description: 'Do not retry with fee_account: call again without it, or ask the user what the gap is.' },
  )
}

/**
 * A kontantmetod invoice that was never booked settles only in one payment of
 * its whole amount (cashPartialBlockReason): the approval refuses anything
 * else with INVOICE_PAID_CASH_PARTIAL_UNSUPPORTED, so staging refuses it
 * first. When the gap could be a payment provider's fee withheld from its
 * payout (crm#1364), the refusal names fee_account, which settles the invoice
 * in full.
 */
function cashPartialRefusal(details: {
  currency: string
  paid: number
  remaining: number
  reason: 'partial_payment' | 'previously_partially_paid'
  feeShaped: boolean
}): Error {
  const amount = (n: number) => `${AGENT_AMOUNT_FORMAT.format(n)} ${details.currency}`
  const shortfall = roundOre(details.remaining - details.paid)
  const state =
    details.reason === 'partial_payment'
      ? `the transaction (${amount(details.paid)}) does not settle the remaining ${amount(details.remaining)}`
      : 'the invoice is already part-paid'
  const manual = 'book the payment as its own verifikat with gnubok_create_voucher.'
  const route = details.feeShaped
    ? `If the ${amount(shortfall)} gap is a fee a payment provider (Stripe, PayPal, Klarna, SumUp) withheld from its payout, ` +
      `call again with fee_account: "${PAYMENT_FEE_ACCOUNT}": the invoice settles in full, revenue and VAT on the full amount ` +
      `and the fee on ${PAYMENT_FEE_ACCOUNT} (no VAT). Otherwise ${manual}`
    : `Do not retry unchanged: ${manual}`
  return codedRefusal(
    'INVOICE_PAID_CASH_PARTIAL_UNSUPPORTED',
    `Not staged: under the cash method an invoice that was never booked settles only in one payment of its whole amount, and ${state}. ${route}`,
    {
      description: details.feeShaped
        ? `Ask the user whether the gap is the payment provider's fee; if so call again with fee_account "${PAYMENT_FEE_ACCOUNT}".`
        : 'Do not retry this match unchanged: book the payment with gnubok_create_voucher.',
    },
  )
}

/**
 * Stage-time twin of the commit executor's payment plan for a
 * transaction-to-invoice match: the same planTransactionInvoiceMatch call
 * (FX resolution, pure-SEK öre absorption, the remaining amount after earlier
 * partial payments), throwing the refusal the approval would answer with, so
 * no doomed op is staged (crm#253). The executor re-runs the plan as the hard
 * gate. A rate that is not available yet fails open: it can be published
 * before approval. Returns the plan (with the excess or the fee the verifikat
 * will book on the named account), or null when the rate is not out yet.
 */
async function refuseUnpayableMatch(
  supabase: SupabaseClient,
  transaction: MatchTransactionAmounts,
  invoice: MatchInvoiceAmounts & { status: string },
  accounts: { overpaymentAccount?: string; feeAccount?: string },
): Promise<Extract<MatchPaymentPlanResult, { ok: true }> | null> {
  const matchPlan = await planTransactionInvoiceMatch(supabase, transaction, invoice, accounts)
  if (matchPlan.ok) return matchPlan
  if (matchPlan.code === 'MATCH_INVOICE_FX_RATE_UNAVAILABLE') return null
  if (matchPlan.code === 'MATCH_AMOUNT_EXCEEDS_REMAINING') {
    throw overpaymentRefusal(matchPlan, { invoiceStatus: invoice.status, transactionDate: transaction.date })
  }
  if (matchPlan.code === 'MATCH_OVERPAYMENT_ROUNDING_CAP') throw roundingCapRefusal(matchPlan)
  if (matchPlan.code === 'MATCH_PAYMENT_FEE_NOT_ALLOWED') throw paymentFeeRefusal(matchPlan)
  throw registryError(matchPlan.code)
}

/**
 * The stage-time twin of the executor's kontantmetoden guard: a never-booked
 * invoice on a cash-method company settles only in one payment of its whole
 * amount. The company's method is read only when the plan would be refused
 * under it (a partial, or completing an invoice already part-paid), so a
 * plain settlement costs no read.
 */
async function refuseCashPartialMatch(
  supabase: SupabaseClient,
  companyId: string,
  invoice: MatchInvoiceAmounts & { journal_entry_id?: string | null },
  plan: Extract<MatchPaymentPlanResult, { ok: true }>,
): Promise<void> {
  const block = (accountingMethod: string) =>
    cashPartialBlockReason({
      invoiceAlreadyBooked: !!invoice.journal_entry_id,
      accountingMethod,
      priorPaidAmount: invoice.paid_amount,
      paysRemainingInFull: plan.plan.isFullyPaid,
    })
  if (!block('cash')) return
  const settingsRead = await supabase
    .from('company_settings')
    .select('accounting_method')
    .eq('company_id', companyId)
    .maybeSingle()
  // Fail closed (accounted#58): a failed read refuses the staging instead of
  // passing a kontantmetod partial as faktureringsmetoden.
  const reason = block(requireAccountingMethod(settingsRead))
  if (!reason) return
  const remaining = roundOre(invoice.remaining_amount ?? invoice.total - (invoice.paid_amount || 0))
  // Pure SEK as the plan decides it: the same currency on both sides (no FX
  // step), and that currency the ledger's.
  const pureSek = !plan.fx.required && isLedgerCurrency(invoice.currency)
  const fee = pureSek && reason === 'partial_payment' ? paymentFeeShortfall(remaining, plan.paidAmount) : 0
  throw cashPartialRefusal({
    currency: invoice.currency,
    paid: plan.paidAmount,
    remaining,
    reason,
    feeShaped: fee > 0 && paymentFeeAllowed(PAYMENT_FEE_ACCOUNT, fee, remaining),
  })
}

/** The approval-card line naming where an overpayment is booked. */
function overpaymentStageNote(overpayment: { account: string; amount: number }): string {
  const amount = `${overpayment.amount.toLocaleString('sv-SE', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} kr`
  return overpayment.account === CUSTOMER_ADVANCE_ACCOUNT
    ? `Överskottet ${amount} bokförs på 2420 Förskott från kunder, en skuld till kunden som återbetalas eller kvittas mot en senare faktura.`
    : `Överskottet ${amount} bokförs som kronutjämning på 3740.`
}

/** The approval-card line naming the payment provider's fee and where it is booked. */
function paymentFeeStageNote(fee: { account: string; amount: number }): string {
  const amount = `${fee.amount.toLocaleString('sv-SE', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} kr`
  return (
    `Mellanskillnaden ${amount} är betaltjänstens avgift och bokförs på ${fee.account} Bankkostnader, utan moms (betaltjänst). ` +
    'Fakturan blir betald i sin helhet. Bokför inte samma avgift igen från betaltjänstens faktura.'
  )
}

export interface McpTool {
  name: string
  // Top-level Tool.title per MCP spec 2025-06-18 (human-facing label for
  // directory listings; distinct from annotations.title). Short Title Case
  // noun phrase. Flows out via the tools/list serializer below.
  title?: string
  description: string
  inputSchema: Record<string, unknown>
  outputSchema?: Record<string, unknown>
  annotations: McpToolAnnotations
  /** Wide or specialized tools discoverable through gnubok_search_tools only. */
  catalogVisibility?: 'default' | 'search'
  // Matcher-side search synonyms (mainly Swedish domain terms like
  // "verifikat", "kundfaktura", "avstämning") folded into gnubok_search_tools
  // matching only. NEVER serialized: keywords must not appear in tools/list
  // or search_tools output; the tools/list payload budget has zero headroom.
  // Store lowercase.
  keywords?: string[]
  // Arguments the tool accepts without declaring them in inputSchema, so they
  // cost nothing in tools/list (payload-size.bench.test.ts): the unknown-
  // argument guard (arg-guard.ts) lets exactly these through: preview_token
  // on the generated staging writes (operation-tools.ts), which the dry-run
  // answer that hands the token out announces, and a renamed argument's old
  // spelling (gnubok_create_voucher's acknowledge_warnings). Never serialized.
  undeclaredArgs?: readonly string[]
  // visibility ['app']: a tool only an MCP Apps view calls (isViewOnlyTool).
  _meta?: { ui: { resourceUri?: string; visibility?: Array<'model' | 'app'> } }
  // Result-level UI hint: when set, a call passing render_ui=true gets a
  // _meta.ui.resourceUri on the RESULT, so the host renders the widget only when
  // asked. (Contrast _meta above, on the definition, which renders on every call.)
  uiResourceUri?: string
  // With uiResourceUri: extra result `_meta` for the rendered view only (never
  // in content or structuredContent), added when render_ui=true. Today the
  // approval view's tokens (view-approval.ts). Not serialized into tools/list.
  viewResultMeta?: (result: unknown, ctx: { actor?: ActorContext; keyScopes: ApiKeyScope[] }) => Record<string, unknown> | null
  // Tasks extension: when this predicate returns true for a call from a
  // task-capable client, the dispatcher returns a CreateTaskResult and runs
  // execute() after the response instead of blocking on it. Not serialized
  // into tools/list.
  shouldRunAsTask?: (args: Record<string, unknown>) => boolean
  // Set by withRetryKey (retry-key.ts): a direct write that replays
  // idempotency_key. Read by __tests__/direct-write-retry.test.ts. Not
  // serialized into tools/list.
  retryKey?: true
  // Set by withAgentReasonArg on every staging tool: how it takes the
  // agent's reason (lib/pending-operations/agent-reason.ts). Every caller of
  // execute() splits it off with splitAgentReason first. Not serialized.
  agentReason?: AgentReasonArg
  execute: (
    args: Record<string, unknown>,
    companyId: string,
    userId: string,
    supabase: SupabaseClient,
    actor?: ActorContext
  ) => Promise<unknown>
}

