const log = createLogger('mcp-server')

/**
 * The largest audit package gnubok_audit_package builds: it is saved as one
 * object in the documents bucket, whose cap per object is 50 MB
 * (storage.buckets.file_size_limit).
 */
const AUDIT_PACKAGE_MAX_BYTES = 50 * 1024 * 1024

/**
 * The operation a generated tool was made from, by tool name: the package
 * start gate (lib/modules/package-doors.ts) classifies a generated tool by
 * its operation. Dark operations included, as the commit path finds them.
 */
/**
 * The briefing's view of the packages that wind down: each with the
 * obligations that keep it visible, as codes and one Swedish phrase. Empty
 * (no key at all) for a company where nothing winds down.
 */
function windingDownBriefing(capabilities: CompanyCapabilities): {
  packages_winding_down?: Array<{ package_id: string; name_sv: string; open_obligations: string[]; open_obligations_sv: string }>
} {
  const winding = capabilities.packages.filter((p) => p.availability === 'winding_down')
  if (winding.length === 0) return {}
  return {
    packages_winding_down: winding.map((p) => ({
      package_id: p.id,
      name_sv: p.name_sv,
      open_obligations: [...p.open_obligations],
      open_obligations_sv: obligationsPhraseSv(p.open_obligations),
    })),
  }
}

const OPERATION_ID_BY_TOOL: ReadonlyMap<string, string> = new Map(
  ALL_OPERATIONS.flatMap((op) => (op.mcp ? [[op.mcp.name, op.id] as const] : [])),
)
const OPERATION_BY_TOOL = new Map(ALL_OPERATIONS.flatMap((op) => (op.mcp ? [[op.mcp.name, op] as const] : [])))

// gnubok_feedback rate limit: 1 per 60s per actor. In-memory single-process;
// no Redis dependency. See the gnubok_feedback tool definition below.
const FEEDBACK_RATE_LIMIT_MS = 60_000
/** How long gnubok_feedback waits for its event's handlers before it answers (the rest finishes after the answer). */
const FEEDBACK_EMIT_WAIT_MS = 10_000
const feedbackRateLimit = new Map<string, number>()

const VALID_CATEGORIES = [
  'income_services', 'income_products', 'income_other',
  'expense_equipment', 'expense_software', 'expense_travel', 'expense_office',
  'expense_marketing', 'expense_professional_services', 'expense_education',
  'expense_representation', 'expense_consumables', 'expense_vehicle',
  'expense_telecom', 'expense_bank_fees', 'expense_card_fees',
  'expense_currency_exchange', 'expense_other', 'private',
] as const

const VALID_VAT_TREATMENTS = [
  'standard_25', 'reduced_12', 'reduced_6', 'reverse_charge', 'export', 'exempt',
] as const

/**
 * gnubok_categorize_transaction also takes reverse charge with its basis box
 * named (reverse_charge_eu_services etc., the chart's own vocabulary). Each
 * resolves at the boundary to vat_treatment 'reverse_charge' plus a
 * ReverseChargeKind, so everything behind the tool keeps one VatTreatment.
 */
const CATEGORIZE_VAT_TREATMENTS = [
  ...VALID_VAT_TREATMENTS,
  ...(Object.keys(REVERSE_CHARGE_TREATMENT_KINDS) as Array<keyof typeof REVERSE_CHARGE_TREATMENT_KINDS>),
]

/** Split a categorize vat_treatment into the booking treatment and the reverse-charge kind it names. */
function splitCategorizeVatTreatment(value: unknown): {
  vatTreatment: VatTreatment | undefined
  reverseChargeKind: ReverseChargeKind | undefined
} {
  if (typeof value !== 'string' || value === '') return { vatTreatment: undefined, reverseChargeKind: undefined }
  const kind = (REVERSE_CHARGE_TREATMENT_KINDS as Record<string, ReverseChargeKind>)[value]
  return kind
    ? { vatTreatment: 'reverse_charge', reverseChargeKind: kind }
    : { vatTreatment: value as VatTreatment, reverseChargeKind: undefined }
}

/**
 * Where a categorize preview's reverse-charge basis lands, read off the lines
 * the approval will post: the box, and whether the caller chose it, the
 * underlag's seller gave it (#94), the cost account reports it itself
 * (crm#1454: 4531 is ruta 22 whatever the default says) or the EU-services
 * default did. Undefined when the lines carry no fiktiv moms.
 */
function reverseChargeBasisSummary(
  vatLines: Array<{ account_number: string; debit_amount: number }>,
  reverseChargeKind: ReverseChargeKind | undefined,
  costAccount: string,
  source: 'vat_treatment' | 'underlag' = 'vat_treatment',
  ownAccount: { kind: ReverseChargeKind; ruta: string } | null = null,
): Record<string, unknown> | undefined {
  if (!vatLines.some((l) => ['2614', '2624', '2634'].includes(l.account_number))) return undefined
  const basisLine = vatLines.find((l) => l.debit_amount > 0 && isReverseChargeBasisAccount(l.account_number))
  if (!basisLine && ownAccount) {
    const read = reverseChargeKind && reverseChargeKind !== ownAccount.kind
      ? ` The ${source === 'underlag' ? 'underlag' : 'vat_treatment'} reads ${reverseChargeKindRuta(reverseChargeKind)}: book another cost account if that is right.`
      : ''
    return {
      kind: ownAccount.kind,
      kind_source: 'account',
      basis_account: null,
      ruta: ownAccount.ruta,
      note: `Cost account ${costAccount} reports ${ownAccount.ruta} itself, so no 45xx/4598 basis pair (it would count the purchase twice).${read}`,
    }
  }
  const kind = reverseChargeKind ?? DEFAULT_REVERSE_CHARGE_KIND
  const kindSource = reverseChargeKind ? source : 'default'
  if (!basisLine) {
    return {
      kind,
      kind_source: kindSource,
      basis_account: null,
      ruta: null,
      note: `No 45xx/4598 basis pair: cost account ${costAccount} reports rutor 20-24 itself, a pair would count the purchase twice.`,
    }
  }
  const ruta = reverseChargeKindRuta(kind)
  return {
    kind,
    kind_source: kindSource,
    basis_account: basisLine.account_number,
    ruta,
    note: reverseChargeKind
      ? `Basis ${basisLine.account_number} D / 4598 K reports the purchase in ${ruta}` +
        (source === 'underlag' ? ", the box the seller country on the underlag gives." : '.')
      : `Seller country not stated, so the basis defaults to EU services (${basisLine.account_number}, ${ruta}). ` +
        'Re-stage with vat_treatment reverse_charge_non_eu_services (ruta 22) or reverse_charge_eu_goods (ruta 20) if the underlag says otherwise.',
  }
}

const MCP_DOCUMENT_MIME_TYPES = [
  'application/pdf',
  'image/jpeg',
  'image/png',
  'image/heic',
  'image/webp',
] as const

const MCP_DOCUMENT_MIME_TYPE_SET = new Set<string>(MCP_DOCUMENT_MIME_TYPES)

/**
 * The file name an upload tool was called with. Hosts do not reliably enforce
 * the inputSchema's required list, and the name used to reach `.split` as
 * undefined (crm#1474): a missing name is a VALIDATION_ERROR, never a
 * TypeError.
 */
function requireMcpFileName(value: unknown): string {
  if (typeof value !== 'string' || value.trim() === '') {
    throw codedError('VALIDATION_ERROR', 'file_name is required: the file name with its extension, for example "faktura.pdf".')
  }
  return value
}

function resolveMcpDocumentMimeType(fileName: string, requestedMimeType: unknown): string {
  let mimeType = typeof requestedMimeType === 'string' ? requestedMimeType : undefined
  if (!mimeType) {
    const extension = fileName.split('.').pop()?.toLowerCase()
    const mimeMap: Record<string, string> = {
      pdf: 'application/pdf',
      jpg: 'image/jpeg',
      jpeg: 'image/jpeg',
      png: 'image/png',
      heic: 'image/heic',
      webp: 'image/webp',
    }
    mimeType = extension ? mimeMap[extension] : undefined
    if (!mimeType) throw unsupportedDocumentType(`Cannot infer MIME type from extension: .${extension}. Allowed: PDF, JPEG, PNG, HEIC, WebP`)
  }
  if (!MCP_DOCUMENT_MIME_TYPE_SET.has(mimeType)) {
    throw unsupportedDocumentType(`Unsupported file type: ${mimeType}. Allowed: PDF, JPEG, PNG, HEIC, WebP`)
  }
  return mimeType
}

/**
 * The upload tools archive underlag, a PDF or an image. A CSV, Excel, text or
 * Markdown file was a plain Error, so the agent read UNKNOWN_ERROR, "Något
 * gick fel. Försök igen." (22 calls in 30 days), for a file no retry makes
 * one. The inbox upload route's code, with where such a file goes instead.
 */
function unsupportedDocumentType(messageEn: string): Error {
  return codedRefusal('DOC_UPLOAD_UNSUPPORTED_TYPE', messageEn, {
    description:
      'Send the underlag as a PDF or an image (a text or spreadsheet underlag printed to PDF). A bank statement file ' +
      '(CSV, Excel) is no underlag: send its rows with gnubok_create_transactions, or the user imports it in Accounted ' +
      'under Importera bankfil (/import?mode=bank). A SIE file goes to gnubok_create_sie_upload.',
  })
}

/**
 * An inbox_item_id that names no inbox item of this company, in
 * gnubok_create_voucher and gnubok_create_supplier_invoice_from_inbox. A plain
 * Error, it answered UNKNOWN_ERROR (9 calls in 30 days); 2 of the 6 voucher
 * ids were a document's id.
 */
function inboxItemNotFound(inboxItemId: string): Error {
  return codedRefusal('INBOX_ITEM_NOT_FOUND', `Inbox item ${inboxItemId} not found for this company.`, {
    description:
      'gnubok_list_inbox_items lists the inbox items. A document id is no inbox item id: gnubok_get_document_content ' +
      'with include ["links"] names the inbox item a document came with.',
    tool: 'gnubok_list_inbox_items',
  })
}

interface DocumentInboxResult {
  document_id: string
  inbox_item_id: string | null
  status: string
  extracted_data: Record<string, unknown>
  matched_supplier_id: string | null
  /** The bytes were already in the archive: this is the existing document, nothing new was created. */
  deduplicated?: boolean
  /** With deduplicated: the archived document the bytes already are (the same id as document_id). */
  duplicate_of?: string
  /** No AI reading was made (the company lacks the AI capability): extracted_data is the empty skeleton. */
  extraction_skipped?: boolean
  /** Archived without an inbox item and without a reading, as the caller asked (archiveOnlyResult). */
  archive_only?: boolean
  /** With doc_type on the upload: the document's type after the call (withUploadDocType). */
  doc_type?: string
  /** With doc_type on the upload: why the document kept another type. */
  doc_type_note?: string
  next?: { tool: string; hint: string }
}

/**
 * file_name of the document_attachments row embedded on an inbox item.
 * invoice_inbox_items.document_id points at ONE document, so PostgREST
 * returns the embed as an object, not an array; reading `[0]` of it gave
 * every gnubok_list_inbox_items row file_name null (agent feedback seq
 * 876431). Both shapes are read so a schema change cannot silently null it
 * again.
 */
function embeddedDocumentFileName(embed: unknown): string | null {
  const attachment = (Array.isArray(embed) ? embed[0] : embed) as { file_name?: string | null } | null | undefined
  return attachment?.file_name ?? null
}

/**
 * The canonical door an inbox row came through (lib/intake/sources.ts), from
 * its source, its channel_context (whole, or the intake_stamp/intake_channel
 * JSON paths a list selects) and the upload_source of its embedded document.
 */
function inboxRowIntakeSource(row: {
  source?: unknown
  channel_context?: unknown
  intake_stamp?: unknown
  intake_channel?: unknown
  document_attachments?: unknown
}): IntakeSourceId | null {
  const embed = row.document_attachments
  const attachment = (Array.isArray(embed) ? embed[0] : embed) as { upload_source?: string | null; file_name?: string | null } | null | undefined
  const context = (row.channel_context ?? { intake_source: row.intake_stamp, channel: row.intake_channel }) as { intake_source?: unknown; channel?: unknown }
  return intakeSourceForInboxItem({
    source: typeof row.source === 'string' ? row.source : null,
    channel_context: context,
    document_upload_source: attachment?.upload_source ?? null,
    document_file_name: attachment?.file_name ?? null,
  })
}

/**
 * The same bytes uploaded again land on the document the archive already
 * holds, and the answer says so instead of minting a second inbox item. The
 * first rollout company had one filing uploaded eight times before this;
 * the nightly lint found the copies, the upload never did.
 */
async function alreadyArchivedResult(supabase: SupabaseClient, companyId: string, documentId: string): Promise<DocumentInboxResult> {
  const { data, error } = await supabase
    .from('invoice_inbox_items')
    .select('id, status, extracted_data, matched_supplier_id')
    .eq('company_id', companyId)
    .eq('document_id', documentId)
    .order('created_at', { ascending: true })
    .limit(1)
    .maybeSingle()
  if (error) throw new Error(`Failed to look up the archived document's inbox item: ${error.message}`)
  const item = data as { id: string; status: string; extracted_data: Record<string, unknown> | null; matched_supplier_id: string | null } | null
  return {
    document_id: documentId,
    inbox_item_id: item?.id ?? null,
    status: item?.status ?? 'archived',
    extracted_data: item?.extracted_data ?? {},
    matched_supplier_id: item?.matched_supplier_id ?? null,
    deduplicated: true,
    duplicate_of: documentId,
  }
}

/**
 * The answer for an archive-only upload (crm#1848, lib/documents/archive-only.ts):
 * the document is in the archive and nothing else was made. No inbox item, no
 * AI reading; the stamp on the row keeps Arkiv from queueing it in Underlag
 * while the link is on its way. A retry of the same upload finds the stamp and
 * leaves the row alone; a document that was read since keeps its reading.
 *
 * Nothing in Underlag shows such a document: until it is linked it is listed
 * in Dokument (for companies that see the section) and in gnubok_list_records,
 * so the answer names the link as the next call.
 */
async function archiveOnlyResult(document: { id: string; extraction_model?: string | null }): Promise<DocumentInboxResult> {
  // Stamped once. 'skipped:opted_out' is what the document-extraction extension wrote on this upload's own event
  // (extractionOwner 'none'), also when an earlier attempt died before the stamp; any other stamp is a reading
  // made since, which stays.
  const stamp = document.extraction_model ?? null
  if (stamp === null || stamp === 'skipped:opted_out') {
    await mirrorExtractionToDocument(document.id, { data: null, rawText: null, model: null, skipped: ARCHIVE_ONLY_SKIP })
  }
  return {
    document_id: document.id,
    inbox_item_id: null,
    status: 'archived',
    extracted_data: {},
    matched_supplier_id: null,
    archive_only: true,
    next: {
      tool: 'gnubok_link_documents_to_vouchers',
      hint: 'Archived only: no inbox item, no AI reading, nothing booked. Link document_id to its posted verifikat (one: gnubok_link_document_to_voucher). Until then it is listed only in gnubok_list_records.',
    },
  }
}

/**
 * doc_type on an upload (crm#2016): what the caller says the document is,
 * from the same list Dokument types with. Refused, before anything is
 * archived, outside that list, and as a receipt, supplier invoice or credit
 * note with archive_only: a person's type of those puts the document in
 * Underlag to be booked (invoice-inbox route-from-arkiv.ts), which is what
 * archive_only leaves out.
 */
function readUploadDocType(value: unknown, archiveOnly: boolean): DocType | null {
  if (value === undefined || value === null) return null
  if (!isDocType(value)) {
    throw badArgument('doc_type', `doc_type must be one of ${DOC_TYPES.join(', ')} (got ${JSON.stringify(value)}).`)
  }
  if (archiveOnly && UNDERLAG_DOC_TYPES.includes(value)) {
    throw badArgument(
      'doc_type',
      `doc_type ${value} with archive_only: that type puts the document in Underlag to be booked. Leave doc_type out; linked to its verifikat it files under Bokförda underlag.`,
    )
  }
  return value
}

/**
 * The upload's doc_type, set once the document is in the archive, as a
 * person's type through Dokument's own service (set-type.ts): after the inbox
 * item exists, so the type reaches that item as a retype in Dokument does.
 * It types a document that has none and never replaces a type: a retry, or
 * the same bytes again, changes nothing a person or the model decided.
 * Changing a type is gnubok_set_document_type, which stages.
 */
async function withUploadDocType(
  supabase: SupabaseClient,
  companyId: string,
  userId: string,
  result: DocumentInboxResult,
  docType: DocType | null,
): Promise<DocumentInboxResult> {
  if (!docType) return result
  const { data, error } = await supabase
    .from('document_attachments')
    .select('doc_type')
    .eq('id', result.document_id)
    .eq('company_id', companyId)
    .maybeSingle()
  if (error) throw dbError(error, 'Failed to read the archived document\'s type')
  const current = (data as { doc_type?: string | null } | null)?.doc_type ?? null
  if (current === docType) return { ...result, doc_type: current }
  if (current) {
    return {
      ...result,
      doc_type: current,
      doc_type_note: `Already typed ${current}, kept. To change it: gnubok_set_document_type.`,
    }
  }
  const out = await setDocumentTypeByPerson(supabase, { companyId, documentId: result.document_id, userId, docType })
  if (out.status !== 'set') {
    // The same call again is safe (the upload is idempotent and an untyped document takes the type).
    throw codedRefusal(
      'TRANSIENT_ERROR',
      `Archived as document_id ${result.document_id}, but its type was not saved (${out.status === 'error' ? out.reason : 'not found'}). Retry the same call, or set it with gnubok_set_document_type.`,
    )
  }
  return { ...result, doc_type: docType }
}

async function findCompletedDocumentInboxItem(
  supabase: SupabaseClient,
  companyId: string,
  userId: string,
  inboxItemId: string
): Promise<DocumentInboxResult | null> {
  const { data, error } = await supabase
    .from('invoice_inbox_items')
    .select('id, document_id, status, extracted_data, matched_supplier_id')
    .eq('id', inboxItemId)
    .eq('company_id', companyId)
    .eq('user_id', userId)
    .maybeSingle()
  if (error) throw new Error(`Failed to check completed document upload: ${error.message}`)
  if (!data) return null
  if (data.document_id !== inboxItemId) {
    throw new Error('Upload ID collides with an unrelated inbox item')
  }
  return {
    document_id: data.document_id,
    inbox_item_id: data.id,
    status: data.status,
    extracted_data: (data.extracted_data ?? {}) as Record<string, unknown>,
    matched_supplier_id: data.matched_supplier_id,
  }
}

/** Who fetched an MCP upload, in the arrival's actor shape. */
function mcpArrivalActor(actor: ActorContext | undefined, userId: string): ArrivalActor {
  if (actor?.serviceAccountId) {
    return apiKeyArrivalActor({
      userId,
      apiKeyId: actor.id,
      actor: { type: 'service_account', label: actor.label },
      serviceAccount: { id: actor.serviceAccountId },
    })
  }
  const type: ArrivalActor['type'] = actor?.oauthKey
    ? 'mcp_oauth'
    : actor?.type === 'mcp_oauth' || actor?.type === 'user' || actor?.type === 'cron'
      ? actor.type
      : 'api_key'
  return {
    type,
    user_id: userId,
    ...(actor?.id && (type === 'api_key' || type === 'mcp_oauth') ? { api_key_id: actor.id } : {}),
    ...(actor?.label ? { label: actor.label } : {}),
  }
}

/** Record how an MCP upload came in (best effort), then hand the result on. */
async function withMcpUploadArrival(
  supabase: SupabaseClient,
  companyId: string,
  userId: string,
  actor: ActorContext | undefined,
  result: DocumentInboxResult,
): Promise<DocumentInboxResult> {
  await recordDocumentArrival(supabase, {
    companyId,
    source: 'mcp',
    documentId: result.document_id,
    inboxItemId: result.inbox_item_id,
    fetchedBy: mcpArrivalActor(actor, userId),
  })
  return result
}

async function createDocumentInboxItem(
  supabase: SupabaseClient,
  companyId: string,
  userId: string,
  documentId: string,
  fileName: string,
  mimeType: string,
  buffer: Buffer,
  reservedInboxItemId?: string
): Promise<DocumentInboxResult> {
  if (reservedInboxItemId) {
    const existing = await findCompletedDocumentInboxItem(
      supabase,
      companyId,
      userId,
      reservedInboxItemId,
    )
    if (existing) return existing
  }

  // uploadDocument()/completePendingDocumentUpload() were told this inbox
  // item owns extraction, so the document-extraction extension yielded;
  // the outcome is mirrored onto the document row in its place.
  //
  // The paid OCR (Bedrock) is the `ai` capability, checked here at the OCR
  // call rather than on the tools: a company without it still archives its
  // underlag (BFL 7 kap), with an empty reading the agent fills in through
  // gnubok_set_inbox_extracted_data, exactly as the dashboard upload and v1
  // POST /documents do (upload-and-extract.ts, no_ai_entitlement). The three
  // upload tools used to be gated on `ai` at dispatch, which refused the
  // underlag itself.
  const aiEntitled = await hasCapability(supabase, companyId, CAPABILITY.ai)
  let extracted: InvoiceExtractionResult
  if (aiEntitled) {
    const extraction = await extractAndMirror(documentId, {
      buffer,
      mimeType,
      fileName,
      ownCompany: await fetchOwnCompanyIdentity(supabase, companyId),
    })
    extracted = extraction.data
  } else {
    extracted = emptyResult()
    await mirrorExtractionToDocument(documentId, { data: extracted, rawText: null, model: null, skipped: 'no_ai_entitlement' })
  }

  const matchedSupplierId = await matchSupplierId(supabase, companyId, extracted.supplier)

  // One document, one inbox item (crm#1413): Arkiv classifies the archived document on its own clock and may have
  // queued it while the reading above ran. That item is taken over with this upload's reading and stamp instead of
  // filing a second one beside it (lib/documents/queued-inbox-item.ts).
  const queued = await adoptQueuedInboxItem(
    supabase,
    companyId,
    documentId,
    {
      status: 'received',
      source: 'upload',
      channel_context: { intake_source: 'mcp' },
      extracted_data: extracted as unknown as Record<string, unknown>,
      extraction_skipped: !aiEntitled,
      matched_supplier_id: matchedSupplierId,
      kind_hint: null,
    },
    { ownStamp: 'mcp' },
  )
  if (queued) {
    if (queued.adopted) await stampNewInboxItemIfDocumentLinked(supabase, companyId, documentId)
    return {
      document_id: documentId,
      inbox_item_id: queued.id,
      status: queued.status,
      extracted_data: queued.adopted ? (extracted as unknown as Record<string, unknown>) : (queued.extracted_data ?? {}),
      matched_supplier_id: queued.matched_supplier_id,
      ...(aiEntitled ? {} : { extraction_skipped: true }),
    }
  }

  const { data: inbox, error: inboxError } = await supabase
    .from('invoice_inbox_items')
    .insert({
      // Literal payload keeps the no-phantom-columns scanner able to resolve
      // every column; the legacy path gets an explicit UUID instead of the DB
      // default.
      id: reservedInboxItemId ?? crypto.randomUUID(),
      company_id: companyId,
      user_id: userId,
      status: 'received',
      source: 'upload',
      // The door, which source 'upload' over an 'api' document cannot name by itself (lib/intake/sources.ts).
      channel_context: { intake_source: 'mcp' },
      document_id: documentId,
      extracted_data: extracted as unknown as Record<string, unknown>,
      extraction_skipped: !aiEntitled,
      matched_supplier_id: matchedSupplierId,
    })
    .select('id, status')
    .single()

  if (inboxError) {
    if (reservedInboxItemId) {
      const concurrent = await findCompletedDocumentInboxItem(
        supabase,
        companyId,
        userId,
        reservedInboxItemId,
      )
      if (concurrent) return concurrent
    }
    throw new Error(`Failed to create inbox item: ${inboxError.message}`)
  }
  // Extraction can take minutes and the agent already holds the document id
  // (the upload id): a link to a verifikat committed meanwhile found no inbox
  // row to stamp (agent feedback seq 1003926).
  await stampNewInboxItemIfDocumentLinked(supabase, companyId, documentId)

  return {
    document_id: documentId,
    inbox_item_id: inbox.id,
    status: inbox.status,
    extracted_data: extracted as unknown as Record<string, unknown>,
    matched_supplier_id: matchedSupplierId,
    ...(aiEntitled ? {} : { extraction_skipped: true }),
  }
}

// ── Pending operations staging ───────────────────────────────

/**
 * Param-keys we'll scan for an affärshändelse date when the caller doesn't
 * pass `dateForPeriodCheck` explicitly. Ordered: most-specific first. The
 * first ISO yyyy-MM-dd hit wins. Adding a new field is safe: unknown values
 * just fall through to undefined.
 */
const AUTO_PERIOD_DATE_KEYS = [
  'entry_date',
  'payment_date',
  'invoice_date',
  'date',
  'period_end',
  'period_start',
  'voucher_date',
  'paid_date',
  'transfer_date',
] as const

const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/

/**
 * The since..until window (both inclusive) of gnubok_list_verifikat_without_documents
 * and gnubok_receipt_hunt_worklist. Both bounds are checked: a date the RPC
 * cannot read failed as a database error, and a since that was not a string
 * was dropped unread.
 */
function sinceUntilArgs(args: Record<string, unknown>): { since: string | null; until: string | null } {
  const [since, until] = (['since', 'until'] as const).map((key) => {
    const value = args[key]
    if (value === undefined || value === null) return null
    if (typeof value !== 'string' || !ISO_DATE_RE.test(value)) {
      throw badArgument(key, `${key} must be an ISO date (YYYY-MM-DD).`)
    }
    return value
  })
  if (since && until && since > until) throw badArgument('since', 'since must not be after until.')
  return { since, until }
}

/**
 * A tool's qr_mode argument: one of INVOICE_QR_MODES, or null/omitted for
 * the company default (invoice_qr_mode). Anything else is refused the way
 * InvoiceQrModeSchema refuses it on the web API.
 */
function parseQrModeArg(value: unknown): InvoiceQrMode | null {
  if (value === undefined || value === null) return null
  if (typeof value === 'string' && (INVOICE_QR_MODES as readonly string[]).includes(value)) {
    return value as InvoiceQrMode
  }
  throw codedError('VALIDATION_ERROR', `qr_mode must be one of ${INVOICE_QR_MODES.join(', ')}, or null.`)
}

/**
 * A tool's delivery_address argument (crm#1547), validated and normalized by
 * InvoiceDeliveryAddressSchema, the web API's own: null or an empty address
 * is none (and clears on update).
 */
function parseDeliveryAddressArg(value: unknown): InvoiceDeliveryAddress | null {
  const parsed = InvoiceDeliveryAddressSchema.nullable().safeParse(value)
  if (!parsed.success) {
    throw fieldValidationError(
      'Invalid delivery_address',
      zodFieldIssues(parsed.error, value).map((issue) => ({
        ...issue,
        field: issue.field === 'arguments' ? 'delivery_address' : `delivery_address.${issue.field}`,
      })),
    )
  }
  return parsed.data
}

/**
 * `reason` is capped at 500 characters (inputSchema maxLength). Hosts do not
 * always enforce inputSchema, so the tools re-check at runtime.
 */
function reasonTooLongError(): Error {
  return badArgument('reason', 'reason must be 500 characters or fewer', 'Motiveringen får vara högst 500 tecken.')
}

/**
 * Coerce a single account-number argument to a trimmed string (validated
 * against ACCOUNT_NUMBER_RE from lib/invariants/account-number). Accepts a
 * string or a finite integer (hosts that skip inputSchema validation send
 * `1930` as a JSON number); everything else is a validation error rather than
 * a silently dropped filter.
 */
function normalizeAccountNumber(value: unknown, field: string): string | undefined {
  if (value === undefined || value === null || value === '') return undefined
  const str =
    typeof value === 'number' && Number.isInteger(value)
      ? String(value)
      : typeof value === 'string'
        ? value.trim()
        : null
  if (str === null || !ACCOUNT_NUMBER_RE.test(str)) {
    throw badArgument(field, `${field} must be an account number string like "1930" (got ${JSON.stringify(value)})`)
  }
  return str
}

/**
 * Coerce an `accounts` argument to string[]. Accepts an array of
 * strings/integers, a bare string ("1930" or comma-separated "1930,1940"), or
 * a bare integer. Returns undefined for null/empty so callers fall through to
 * account_from/account_to.
 */
function normalizeAccountList(value: unknown): string[] | undefined {
  if (value === undefined || value === null) return undefined
  const raw: unknown[] = Array.isArray(value)
    ? value
    : typeof value === 'string'
      ? value.split(',')
      : [value]
  const list = raw
    .filter((v) => v != null && !(typeof v === 'string' && v.trim() === ''))
    .map((v) => normalizeAccountNumber(v, 'accounts') as string)
  return list.length > 0 ? list : undefined
}

/**
 * Coerce a voucher_number_from/to argument to a number. Hosts don't enforce
 * inputSchema types, and query_journal only applied the filter to a number:
 * "12" or "A12" skipped it while applied_filters still echoed the value, so
 * the whole journal came back labelled as voucher 12. A digit string is read
 * as its number; any other non-number is refused.
 */
function normalizeVoucherNumber(value: unknown, field: string): number | undefined {
  if (value === undefined || value === null) return undefined
  if (typeof value === 'number' && Number.isFinite(value)) return value
  if (typeof value === 'string' && /^\d+$/.test(value.trim())) return Number(value.trim())
  throw codedError(
    'VALIDATION_ERROR',
    `${field} must be a voucher number like 12 (got ${JSON.stringify(value)}). ` +
      'Pass the series separately as voucher_series, e.g. "A".',
  )
}

/**
 * gnubok_query_journal's date_from / date_to: one calendar date each. They
 * went to SQL as given, so a day past the month end ("2026-09-31"), a range
 * in one field ("2022-10-01 2023-09-30") or "0" failed the date cast and
 * answered UNKNOWN_ERROR "try again" for a call no retry fixes. The forms
 * the cast took keep working (an unpadded month or day, a trailing time,
 * YYYYMMDD) and are passed on as YYYY-MM-DD. Empty or null is no bound.
 * gnubok_list_uncategorized_transactions reads its date_from / date_to here too.
 */
const JOURNAL_DATE_RE = /^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ]\d{1,2}:\d{2}(?::\d{2}(?:\.\d+)?)?(?:Z|[+-]\d{2}(?::?\d{2})?)?)?$/
const COMPACT_DATE_RE = /^(\d{4})(\d{2})(\d{2})$/

function normalizeJournalDate(value: unknown, field: 'date_from' | 'date_to'): string | undefined {
  if (value === undefined || value === null || value === '') return undefined
  const text = typeof value === 'string' ? value.trim() : typeof value === 'number' ? String(value) : ''
  const parts = JOURNAL_DATE_RE.exec(text) ?? COMPACT_DATE_RE.exec(text)
  if (!parts) {
    throw badArgument(
      field,
      `${field} must be one date, YYYY-MM-DD (got ${JSON.stringify(value)}); a range is date_from plus date_to.`,
      'Ange ett datum som ÅÅÅÅ-MM-DD.',
    )
  }
  const [year, month, day] = [Number(parts[1]), Number(parts[2]), Number(parts[3])]
  const iso = `${parts[1]}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0
  const monthEnd = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1]
  if (monthEnd === undefined || day < 1 || day > monthEnd) {
    throw badArgument(
      field,
      monthEnd === undefined
        ? `${field} ${iso} is not a date: the month must be 01-12.`
        : `${field} ${iso} does not exist: that month ends on ${iso.slice(0, 8)}${monthEnd}.`,
      monthEnd === undefined ? 'Datumet finns inte: månaden ska vara 01-12.' : `Datumet finns inte: månaden slutar den ${monthEnd}.`,
    )
  }
  return iso
}

function autoExtractDateForPeriodCheck(params: Record<string, unknown>): string | undefined {
  for (const key of AUTO_PERIOD_DATE_KEYS) {
    const value = params[key]
    if (typeof value === 'string' && ISO_DATE_RE.test(value)) return value
  }
  return undefined
}

interface StageOptions {
  /**
   * When true, validate inputs and return the would-be preview without
   * inserting into pending_operations or executing any side-effects. Used
   * by agents to preflight an operation before committing to it.
   */
  dryRun?: boolean
  /**
   * Per-operation idempotency key. When supplied, repeat calls with the same
   * key + same payload return the original response and never re-execute.
   * Different payload + same key returns IDEMPOTENCY_KEY_REUSE.
   */
  idempotencyKey?: string
  /**
   * Payload hashed for the idempotency replay check instead of `params`.
   * Needed when params carry a non-deterministic derivative of the input
   * (random-IV ciphertext, see gnubok_create_customer): hashing params would
   * make an identical retry look like a different payload and fail with
   * IDEMPOTENCY_KEY_REUSE. Must itself be free of plaintext PII.
   */
  idempotencyParams?: Record<string, unknown>
  /**
   * ISO yyyy-MM-dd date used to look up period_status before staging. When
   * provided, the response includes a `period_status` envelope so agents and
   * widgets can detect locked/closed periods without a round-trip. Failure to
   * resolve (DB blip, missing settings row) leaves the response unchanged:
   * the DB triggers remain the authoritative gate. When the operation posts
   * a verifikat on this date, list its type in
   * lib/pending-operations/period-lock.ts: the staged message and the
   * approval queue then say when the date is locked.
   */
  dateForPeriodCheck?: string
  /**
   * Advisory compliance warning. Appended to the staged message and echoed as
   * preview.compliance_warning, which persists into preview_data so the
   * /pending approval card carries the same warning. Never blocks: the DB
   * triggers and the approver stay authoritative.
   */
  complianceNote?: string
}

/**
 * Fold the invoice VAT-treatment explanation (explainVatTreatment, #2749 and
 * #2558) into the staging message as the existing WARNING channel. The
 * structured list itself is staged as preview.vat_warnings; this is the
 * prose the agent reads in the tool result. English: the surrounding message
 * is English and the approval card renders the Swedish sentence from the
 * structured field, not from compliance_warning.
 */
function vatWarningsStageOptions(warnings: InvoiceVatWarning[]): Pick<StageOptions, 'complianceNote'> {
  if (warnings.length === 0) return {}
  return { complianceNote: warnings.map((warning) => `${warning.code}: ${warning.message_en}`).join(' ') }
}

// Keys that can stage typically lack pending_operations:approve (segregation
// of duties, see STAGING_SCOPES in lib/auth/api-keys.ts), so the approve tool
// is filtered out of their tools/list. Every staging response names the web
// fallback so agents on such keys don't hunt for a tool they cannot see.
const APPROVE_SCOPE_FALLBACK =
  'If that tool is missing from your catalog, this API key lacks the pending_operations:approve scope: the user approves at /pending instead.'

/**
 * Where a person reviews staged operations: absolute on a deployment that
 * knows its origin, so the agent can hand the user a link, else the path.
 */
function pendingReviewLink(): string {
  return appUrl('/pending')
}

/**
 * What the agent does with a staged operation next. A key without
 * pending_operations:approve (the default one-click connection since issue
 * #3408) cannot approve here at all, so it is told that outright, with the
 * link to give the user: the conditional fallback left agents calling a tool
 * they did not have or saying nothing, and their operations waited unseen
 * (239 still pending after two hours in 30 days). The fallback stays only
 * where the scopes are unknown.
 */
function buildApprovalGuidance(
  operationId: string,
  riskLevel: 'low' | 'medium' | 'high',
  canApprove?: boolean,
): string {
  if (canApprove === false) {
    return `This connection cannot approve: its key lacks the pending_operations:approve scope, so gnubok_approve_pending_operation is refused here and no bridge carries it. Tell the user the proposal is waiting for them at ${pendingReviewLink()} and that nothing is booked until they approve it there.`
  }
  const fallback = canApprove === undefined ? ` ${APPROVE_SCOPE_FALLBACK}` : ''
  if (riskLevel === 'high') {
    return `This is an irreversible posting under BFL 5 kap 5§: surface the irreversibility implications, and any compliance_warning in the preview, to the user and obtain an explicit acknowledgment before committing. Once the user has acknowledged, call gnubok_approve_pending_operation with operation_id="${operationId}" and confirmed=true.${fallback}`
  }
  return `When the user authorises, call gnubok_approve_pending_operation with operation_id="${operationId}".${fallback}`
}

/** The approve hint of a staged answer: none for a key that cannot approve here. */
function approveHint(operationId: string, companyId: string, actor: ActorContext) {
  return actor.canApprove === false
    ? {}
    : { approve: { tool: 'gnubok_approve_pending_operation', args: { operation_id: operationId, company_id: companyId } as Record<string, unknown> } }
}

/**
 * gnubok_bulk_book_transactions: resolve-don't-select for its dimension bags
 * (./dimensions.ts). The operation transactions.bulk-book (the v1 contract)
 * takes registry codes; an agent may also send a name ("Villa Almgren tak").
 * Manual lines and the header default are resolved in one pass and stay
 * apart: the operation puts the default on the business lines only, never
 * on the bank side or a moms line (crm#1313), and the staged lines then
 * carry what the approver saw (pinParams); a template's header default is
 * resolved on its own. Every non-exact resolution is echoed in the staged
 * preview so the agent can verify what a name attached to. A link to a
 * posted verifikat carries no tags (the input refuses them), so it is left
 * alone.
 */
async function prepareBulkBookDimensions(
  args: Record<string, unknown>,
  { supabase, companyId }: { supabase: SupabaseClient; companyId: string },
): Promise<{ args: Record<string, unknown>; preview?: Record<string, unknown> }> {
  if (args.existing_journal_entry_id) return { args }
  const defaults = parseDimensionsArg(args.default_dimensions, 'default_dimensions')
  const echo = (resolutions: DimensionResolution[]) =>
    resolutions.length > 0 ? { preview: { dimension_resolutions: resolutions } } : {}
  if (Array.isArray(args.manual_lines)) {
    const lines = args.manual_lines as Array<Record<string, unknown>>
    const { bags, resolutions } = await resolveDimensionBags(supabase, companyId, [
      defaults,
      ...lines.map((l, i) => parseDimensionsArg(l.dimensions, `manual_lines[${i}].dimensions`)),
    ])
    const [resolvedDefaults, ...lineBags] = bags
    const { default_dimensions: _raw, ...rest } = args
    return {
      args: {
        ...rest,
        ...(resolvedDefaults ? { default_dimensions: resolvedDefaults } : {}),
        manual_lines: lines.map((l, i) => {
          const { dimensions: _rawLine, ...line } = l
          const bag = lineBags[i]
          return bag && Object.keys(bag).length > 0 ? { ...line, dimensions: bag } : line
        }),
      },
      ...echo(resolutions),
    }
  }
  if (!defaults) return { args }
  const { bags, resolutions } = await resolveDimensionBags(supabase, companyId, [defaults])
  return { args: { ...args, default_dimensions: bags[0] }, ...echo(resolutions) }
}

async function stagePendingOperation(
  supabase: SupabaseClient,
  companyId: string,
  userId: string,
  operationType: string,
  title: string,
  params: Record<string, unknown>,
  previewData: Record<string, unknown>,
  actor: ActorContext = { type: 'user' },
  next?: NextActionHint,
  options: StageOptions = {}
): Promise<{
  staged: boolean
  dry_run?: boolean
  idempotency_replay?: boolean
  operation_id?: string
  /** The proposal's number in its company ("Förslag 128"); none while the column is not there yet. */
  operation_number?: number
  /** Older proposals of this stager for the same bank rows (crm#1264), or identical ones, rejected as superseded. */
  superseded_operation_ids?: string[]
  /** A dry run's: the proposals staging would supersede. */
  would_supersede_operation_ids?: string[]
  risk_level: 'low' | 'medium' | 'high'
  actor: ActorContext
  message: string
  approve?: { tool: string; args: Record<string, unknown> }
  preview: Record<string, unknown>
  period_status?: PeriodStatusForDate
  next?: NextActionHint
}> {
  // PII chokepoint (ISO 27001 A.8.11): no staged payload may persist a
  // plaintext personnummer. Enforced here so every current and future
  // staging tool inherits the rule, not just the ones that remembered it.
  assertNoPlaintextPersonnummer(params, 'params')
  assertNoPlaintextPersonnummer(previewData, 'preview_data')

  // An approval that would change the moms of a period already declared is
  // said to the stager and the approver like any other advisory
  // (lib/pending-operations/filed-vat-note.ts).
  const filedVatNote = await stagedFiledVatNote(
    supabase,
    companyId,
    { operation_type: operationType, params, preview_data: previewData },
    log,
  )
  const complianceNote = [options.complianceNote, filedVatNote].filter((note): note is string => !!note).join(' ')

  // Fold the advisory compliance note into the preview so the agent response
  // and the persisted preview_data (rendered by the /pending approval card)
  // carry the same warning.
  if (complianceNote) {
    previewData = { ...previewData, compliance_warning: complianceNote }
  }

  // params-aware: create/update_recurring_schedule escalate to 'high' when
  // params.auto_send === true (standing outbound email with no per-send
  // approval, same side-effect that puts one-off send_invoice at 'high').
  // Ops whose persisted params nest the effective fields under `changes`
  // (update_recurring_schedule: { schedule_id, changes }) are flattened for
  // the risk check ONLY, so paramEscalatedRisk sees auto_send; the stored
  // params row is untouched (the commit executor's schema owns that shape).
  const changesBag = params.changes
  const riskParams =
    changesBag && typeof changesBag === 'object' && !Array.isArray(changesBag)
      ? { ...params, ...(changesBag as Record<string, unknown>) }
      : params
  const riskLevel = getRiskLevel(operationType, riskParams)
  // Inside gnubok_stage_across_companies, a dry run included, a high-risk
  // operation is refused here on the tier this row would carry.
  assertStageableInBatch(operationType, riskLevel)
  const branding = getBranding().appName.toLowerCase()

  // Resolve period_status once. The caller can pass `dateForPeriodCheck`
  // explicitly; otherwise we scan params for a known affärshändelse-date
  // field so every date-bearing operation surfaces a period_status envelope
  // without each tool having to opt in. Failure is non-fatal: DB triggers
  // are the authoritative gate; a missing envelope just degrades preview UX.
  const dateForPeriodCheck = options.dateForPeriodCheck ?? autoExtractDateForPeriodCheck(params)
  let periodLock: PeriodLockForDate | undefined
  if (dateForPeriodCheck) {
    try {
      periodLock = await resolvePeriodLockForDate(supabase, companyId, dateForPeriodCheck)
    } catch (err) {
      log.warn('resolvePeriodLockForDate failed', {
        operationType,
        companyId,
        dateForPeriodCheck,
        error: err instanceof Error ? err.message : String(err),
      })
      periodLock = undefined
    }
  }
  const periodStatus: PeriodStatusForDate | undefined = periodLock?.status
  // A posting on a date that is locked now is still staged (the person may
  // unlock first), but the answer says so in words and what to do: with only
  // period_status in the envelope the proposal read as approvable (crm#1923).
  // Only for the operation types that post on that date
  // (lib/pending-operations/period-lock.ts); the approval queue reads the
  // same lock when it lists the proposal, so nothing about it is stored.
  const periodLockNote = stagedPeriodLockNote(
    { operation_type: operationType, params, preview_data: previewData },
    dateForPeriodCheck,
    periodLock,
  )

  // ── One bank row, one open proposal (crm#1264). Rows another open
  //    operation names are refused, a dry run included, whatever force
  //    says; the same proposal again is answered below as a replay; this
  //    stager's own older proposals the new one fully covers are superseded
  //    once it is staged. A key stages as what it is in the records
  //    (./commit-actor.ts), every other connection as its own type.
  const stagedActorType = actor.type === 'api_key' ? mcpCommitActorType(actor) : actor.type
  const stager = { userId, actorType: stagedActorType, actorId: actor.id ?? null }
  const claim = await checkTransactionClaims(supabase, companyId, operationType, params, stager)
  if (claim.kind === 'claimed') throw transactionAlreadyStagedRefusal(claim.claims)
  const toSupersede = claim.kind === 'supersede' ? claim.operations.map((operation) => operation.id) : []

  // ── Dry-run path: skip both the cache and the insert. Return the preview
  //    so the agent sees exactly what would happen without committing.
  if (options.dryRun) {
    return {
      staged: false,
      dry_run: true,
      risk_level: riskLevel,
      actor,
      message: `Dry run: would stage "${operationType}" (risk: ${riskLevel})${toSupersede.length > 0 ? ` and supersede your pending proposal(s) ${toSupersede.join(', ')} for the same bank rows` : ''}. No changes made.${complianceNote ? ` WARNING: ${complianceNote}` : ''}`,
      ...(toSupersede.length > 0 ? { would_supersede_operation_ids: toSupersede } : {}),
      preview: previewData,
      ...(periodStatus ? { period_status: periodStatus } : {}),
      ...(next ? { next: addCompanyToNextHint(next, companyId) as NextActionHint } : {}),
    }
  }

  // ── Idempotency check: same key + same payload + same company → return
  //    cached response. companyId is folded into the canonical hash so the
  //    same key UUID submitted under a different company is treated as a
  //    fresh request, not a replay.
  const requestHash = options.idempotencyKey
    ? hashRequest({ operationType, params: options.idempotencyParams ?? params, companyId })
    : null
  if (options.idempotencyKey && requestHash) {
    const cached = await checkIdempotencyKey(supabase, userId, companyId, options.idempotencyKey, requestHash)
    if (cached) {
      const cachedBody = cached.body as Record<string, unknown>
      const cachedOpId = typeof cachedBody.operation_id === 'string' ? cachedBody.operation_id : undefined
      return {
        ...cachedBody,
        idempotency_replay: true,
        risk_level: riskLevel,
        actor,
        message: cachedOpId
          ? `Replayed cached response for idempotency_key "${options.idempotencyKey}": already staged as pending_operation ${cachedOpId}. No new side-effects. ${buildApprovalGuidance(cachedOpId, riskLevel, actor.canApprove)}`
          : `Replayed cached response for idempotency_key "${options.idempotencyKey}". No new side-effects.`,
        ...(cachedOpId ? approveHint(cachedOpId, companyId, actor) : {}),
        preview: periodStatus ? { ...previewData, period_status: periodStatus } : previewData,
        ...(periodStatus ? { period_status: periodStatus } : {}),
      } as Awaited<ReturnType<typeof stagePendingOperation>>
    }
  }

  // ── The same proposal for the same bank rows is still pending (a retry
  //    without idempotency_key): answer with that operation, as a keyed
  //    replay does, instead of a second approvable card (crm#1264).
  if (claim.kind === 'replay') {
    const existing = claim.operation
    const existingRisk = existing.risk_level ?? riskLevel
    const existingPreview = existing.preview_data ?? {}
    return {
      staged: true,
      idempotency_replay: true,
      operation_id: existing.id,
      ...operationNumberField(existing),
      risk_level: existingRisk,
      actor,
      message: `Already staged: pending_operation ${existing.id} (staged ${existing.created_at}) holds exactly this proposal for these bank rows, so nothing new was staged. ${buildApprovalGuidance(existing.id, existingRisk, actor.canApprove)}`,
      ...approveHint(existing.id, companyId, actor),
      preview: periodStatus ? { ...existingPreview, period_status: periodStatus } : existingPreview,
      ...(periodStatus ? { period_status: periodStatus } : {}),
      ...(next ? { next: addCompanyToNextHint(next, companyId) as NextActionHint } : {}),
    }
  }

  const agentMetadata = await loadSkillProvenance(supabase, companyId, userId, actor)
  // The tool call's `reason`, split off before the tool ran (request-local,
  // like the batch id).
  const { data, error } = await writeWithTraceId((traceId) => writeWithAgentReason(currentAgentReason(), (agentReason) =>
    supabase
      .from('pending_operations')
      .insert({
        company_id: companyId,
        user_id: userId,
        operation_type: operationType,
        title,
        params,
        preview_data: previewData,
        // A service account's key stages as the service account (its label is
        // the account's name); every other connection as its own type.
        actor_type: stagedActorType,
        actor_id: actor.id ?? null,
        actor_label: actor.label ?? null,
        agent_metadata: agentMetadata,
        risk_level: riskLevel,
        // Set only inside gnubok_stage_across_companies (request-local async
        // context); NULL for every other staging path.
        batch_id: currentStagingBatchId(),
        // The tool call's trace (handleMcpRequest), none outside one.
        ...traceIdColumn(traceId),
        ...agentReasonColumn(agentReason),
      })
      .select('*')
      .single(),
  ))

  if (error) throw new Error(`Failed to stage operation: ${error.message}`)

  // The older proposals this one replaces leave the queue (crm#1264).
  const superseded =
    claim.kind === 'supersede'
      ? await supersedeTransactionClaims(supabase, companyId, claim.operations, {
          operationId: data.id,
          stager,
          actorLabel: actor.label,
          channel: 'mcp',
        })
      : []
  // The same reversal, rättelse or SIE import, staged again by this stager
  // while the first was open (identical-proposal.ts): the older card leaves
  // the queue the same way, instead of waiting out the expiry after its twin
  // was approved.
  const supersededTwins = await supersedeIdenticalProposals(
    supabase,
    companyId,
    { id: data.id, operationType, params, batchId: currentStagingBatchId() },
    { stager, actorLabel: actor.label, channel: 'mcp' },
  )

  // The proposal's number in its company, as the database assigned it: what
  // the person sees as "Förslag 128" (lib/pending-operations/
  // operation-number.ts). None while the column is not there yet. Not in
  // STAGED_OPERATION_SCHEMA, like superseded_operation_ids: every listed
  // staging tool repeats that schema in tools/list, whose budget is frozen.
  const operationNumber = operationNumberOf(data)

  // approve.args carries only the operation_id. For high-risk operations the
  // LLM must supply confirmed=true itself after surfacing the BFL 5 kap 5§
  // irreversibility implications to the user: pre-filling it server-side
  // would collapse the explicit-acknowledgment gate (mirrors the web UI's
  // warning dialog). The server-side check in gnubok_approve_pending_operation
  // remains authoritative.
  const response = {
    staged: true,
    operation_id: data.id,
    ...operationNumberField(data),
    risk_level: riskLevel,
    actor,
    message: `Staged as ${operationNumber ? `proposal ${operationNumber}, ` : ''}pending_operation ${data.id} (risk: ${riskLevel}).${periodLockNote ? ` ${periodLockNote}` : ''}${superseded.length > 0 ? ` It replaces your earlier proposal(s) ${superseded.join(', ')} for the same bank rows, now rejected as superseded.` : ''}${supersededTwins.length > 0 ? ` It replaces your identical earlier proposal(s) ${supersededTwins.join(', ')}, now rejected as superseded.` : ''} ${buildApprovalGuidance(data.id, riskLevel, actor.canApprove)}${actor.canApprove === false ? '' : ` The user can also approve at /pending in the ${branding} web app.`}${complianceNote ? ` WARNING: ${complianceNote}` : ''}`,
    ...(superseded.length + supersededTwins.length > 0 ? { superseded_operation_ids: [...superseded, ...supersededTwins] } : {}),
    ...approveHint(data.id, companyId, actor),
    preview: periodStatus ? { ...previewData, period_status: periodStatus } : previewData,
    ...(periodStatus ? { period_status: periodStatus } : {}),
    ...(next ? { next: addCompanyToNextHint(next, companyId) as NextActionHint } : {}),
  } as const

  if (options.idempotencyKey && requestHash) {
    await storeIdempotencyResponse(
      supabase, userId, companyId, options.idempotencyKey, requestHash,
      'success', { staged: true, operation_id: data.id, ...operationNumberField(data), preview: previewData }
    )
  }
  return response
}
/** What stage() takes: stagePendingOperation's arguments, named. */
interface StageRequest extends StageOptions {
  supabase: SupabaseClient
  companyId: string
  userId: string
  /** The pending_operations.operation_type. */
  type: string
  title: string
  params: Record<string, unknown>
  preview: Record<string, unknown>
  actor?: ActorContext
  next?: NextActionHint
}

/**
 * Stage a pending operation: every hand-written write tool's last step, with
 * named arguments (stagePendingOperation does the work). The staging options
 * (dryRun, idempotencyKey, dateForPeriodCheck, ...) sit beside the rest.
 */
function stage({ supabase, companyId, userId, type, title, params, preview, actor, next, ...options }: StageRequest) {
  return stagePendingOperation(supabase, companyId, userId, type, title, params, preview, actor, next, options)
}

/**
 * The processing_history actor type of a connection: a service account's key
 * as service_account (its label is the account's name), any other key as
 * api_key, everything else as user.
 */
function processingHistoryActorType(actor: ActorContext | undefined): 'user' | 'api_key' | 'service_account' {
  if (actor?.type !== 'api_key') return 'user'
  return actor.serviceAccountId ? 'service_account' : 'api_key'
}

/**
 * The gate both service-account tools run first, the same one the v1 doors
 * run (lib/service-accounts): a person's key, held by an owner or admin of
 * the company. A service account's key never manages service accounts.
 */
async function assertServiceAccountManager(
  supabase: SupabaseClient,
  companyId: string,
  userId: string,
  actor: ActorContext | undefined,
): Promise<void> {
  const refusal = await assertCanManageServiceAccounts(supabase, companyId, {
    userId,
    serviceAccount: actor?.serviceAccountId ? { id: actor.serviceAccountId, name: actor.label ?? '' } : null,
  })
  if (!refusal) return
  throw codedRefusal(
    refusal.code,
    refusal.code === 'SERVICE_ACCOUNT_KEY_NOT_PERMITTED'
      ? "A service account's key cannot manage service accounts: use a key that belongs to an owner or admin."
      : 'Only an owner or admin of the company can manage its service accounts.',
  )
}

/** The customer tools' wire names for the schema fields they map onto. */
const CUSTOMER_WIRE_FIELDS: Record<string, string> = { address_line1: 'address', default_payment_terms: 'payment_terms' }

function wireCustomerFields<T extends { field: string }>(issues: T[]): T[] {
  return issues.map((issue) => ({ ...issue, field: CUSTOMER_WIRE_FIELDS[issue.field] ?? issue.field }))
}

/**
 * A customer row for a staged preview: the record's fields
 * (lib/customers/customer-record.ts) with the personnummer under its masked
 * key, which staging-pii-guard allows; the row's id as customer_id.
 */
function stagedCustomerPreview(row: Record<string, unknown>): Record<string, unknown> {
  const { id, personal_number: personalNumber, party_id: _partyId, archived_at: _archivedAt, created_at: _createdAt, updated_at: _updatedAt, ...rest } =
    toCustomerRecord(row)
  return { ...(id ? { customer_id: id } : {}), ...rest, personal_number_masked: personalNumber ?? null }
}

/** A staged update's changed fields, the personnummer under its masked key. */
function stagedCustomerChanges(changes: Record<string, unknown>): Record<string, unknown> {
  const { personal_number: personalNumber, ...rest } = changes
  return personalNumber === undefined ? rest : { ...rest, personal_number_masked: personalNumber }
}

/** The dry_run and idempotency_key arguments (STAGING_ARGS_PROPERTIES) as staging options. */
function stagingOptions(args: Record<string, unknown>): Pick<StageOptions, 'dryRun' | 'idempotencyKey'> {
  return {
    dryRun: args.dry_run === true,
    idempotencyKey: typeof args.idempotency_key === 'string' ? args.idempotency_key : undefined,
  }
}

/**
 * The account a staged reconciliation title names (./reconciliation-titles.ts).
 * A dry run stores no title, so it reads nothing.
 */
async function stagedAccountLabel(
  supabase: SupabaseClient,
  companyId: string,
  accountKey: string,
  args: Record<string, unknown>,
): Promise<string> {
  return args.dry_run === true ? '' : accountKeyLabel(supabase, companyId, accountKey)
}

// ── Skatteverket filing helpers (PR5) ────────────────────────
//
// Direct lib calls bypass the HTTP dispatcher's SKATTEVERKET_ENABLED gate, so
// every Skatteverket tool gates on it first (before any DB/SKV access).
// mapSkatteverketError re-attaches a registry code to a SkatteverketAuthError
// so toToolError/getStructuredError surface the right structured envelope +
// reconnect remediation (the raw SKV codes aren't registry entries).

function assertSkatteverketEnabled(): void {
  if (!isSkatteverketEnabled()) {
    const err = new Error('Skatteverket-integrationen är inte aktiverad i denna miljö.') as Error & { code: string }
    err.code = 'EXTENSION_DISABLED'
    throw err
  }
}

/**
 * The AR/AP ledgers' as_of_date, by the rules v1 applies (one check,
 * lib/reports/ledger-as-of.ts): an impossible date used to reach the
 * generator and answer an empty or all-overdue ledger.
 */
function ledgerAsOfDateArg(value: unknown): string | undefined {
  const asOf = parseLedgerAsOfDate(value)
  if (!asOf.ok) throw badArgument('as_of_date', `as_of_date: ${asOf.message}`, asOf.messageSv)
  return asOf.asOfDate
}

/**
 * `whenUnavailable`: the sentence the tool adds when Skatteverket gave no
 * answer (skvUnavailableRefusal): what still works without it differs by tool.
 */
function mapSkatteverketError(err: unknown, whenUnavailable: string): Error {
  if (err instanceof SkatteverketAuthError) {
    const mapped = skvAuthCodeToStructured(err.code)
    const out = new Error(err.message) as Error & { code: string }
    out.code = mapped.code
    return out
  }
  if (skvUnreachable(err)) return skvUnavailableRefusal(whenUnavailable)
  return err instanceof Error ? err : new Error(String(err))
}

/**
 * Skatteverket gave no answer: the transport's timeout ran out, or no
 * connection. As the platform's own error it reached the agent as
 * UNKNOWN_ERROR, not retryable, "The operation was aborted due to timeout"
 * (12 calls on 2026-11-05): no word on who had not answered or what to do.
 * The one answer every door gives (skvUnavailableAnswer) says who was silent,
 * that the call can be made again and that the connection is not the
 * problem, so the agent does not send the user to BankID for an outage on
 * Skatteverket's side.
 */
function skvUnavailableRefusal(whenUnavailable: string): Error {
  const answer = skvUnavailableAnswer()
  return codedRefusal(answer.code, `${answer.messageEn} ${whenUnavailable}`)
}

/**
 * A /kontrollera call Skatteverket refused, as a refusal the agent can read:
 * what Skatteverket answered (lib/vat-refusal.ts, the reader every
 * momsdeklaration call shares) under SKATTEVERKET_API_ERROR. A bare Error
 * here reached the agent as UNKNOWN_ERROR with the body as a JSON string.
 */
async function skvKontrolleraRefusal(res: Response): Promise<Error> {
  return codedRefusal('SKATTEVERKET_API_ERROR', (await readVatRefusal(res, 'validate')).message)
}

/**
 * mapSkatteverketError for the filing tools, whose Skatteverket calls run on
 * the CALLER's own BankID session. A bare "Sessionen har gått ut" beside a
 * briefing that said active (another member's session) left the agent
 * nowhere to go (crm#1263): the refusal now says whose session is live and
 * that the caller connects their own, the same words as the briefing's
 * skatteverket_connection.filing. Other failures pass through unchanged.
 */
async function mapFilingSkvError(
  supabase: SupabaseClient,
  companyId: string,
  userId: string,
  err: unknown,
  whenUnavailable: string,
): Promise<Error> {
  const mapped = mapSkatteverketError(err, whenUnavailable)
  if ((mapped as Error & { code?: string }).code !== 'SKATTEVERKET_NOT_CONNECTED') return mapped
  const filing = await getSkvFilingReadiness(supabase, companyId, userId)
  if (!filing?.message) return mapped
  return codedRefusal('SKATTEVERKET_NOT_CONNECTED', filing.message, {
    description:
      "Filing needs the user's own BankID login: call gnubok_connect_skatteverket for the connect_url and give it to the user. Do not retry until they confirm.",
    tool: 'gnubok_connect_skatteverket',
  })
}

/**
 * gnubok_vat_declaration_status without a live Skatteverket session: the
 * read that answers "was this period filed" from Accounted's own record.
 */
const VAT_STATUS_WITHOUT_SKATTEVERKET =
  'gnubok_list_vat_filings needs no connection and lists the periods Accounted has on record as filed (through a Skatteverket kvittens or marked by hand). It is the local record, not what Skatteverket holds.'

/**
 * The read tools' SKATTEVERKET_NOT_CONNECTED, with the filing tools' next
 * step: gnubok_connect_skatteverket, then wait for the user. Its words name
 * the session the read used (skvReadSessionMessage), since a read may run on
 * another member's login or none: never "your own" unless it was.
 */
async function skvReadRefusal(
  supabase: SupabaseClient,
  companyId: string,
  userId: string,
  opts: { meanwhile?: string } = {},
): Promise<Error> {
  // `meanwhile`: what answers the same question without Skatteverket. Only a
  // person can connect, so without it the refusal left the agent nothing to
  // call next (281 gnubok_vat_declaration_status refusals in 14 days, 113
  // companies; 36 in 100 went on to anything that answered the question).
  const message = await skvReadSessionMessage(supabase, companyId, userId)
  return codedRefusal('SKATTEVERKET_NOT_CONNECTED', opts.meanwhile ? `${message} Meanwhile: ${opts.meanwhile}` : message, {
    description:
      'A person signs in to Skatteverket with BankID: call gnubok_connect_skatteverket for the connect_url and give it to the user. Do not retry until they confirm.',
    tool: 'gnubok_connect_skatteverket',
  })
}

// ── Skattekonto row booking (stage side) ─────────────────────
//
// Shape of the skattekonto_transactions columns the book_skattekonto_row(s)
// tools select at stage time (both call sites keep the select string literal
// so the no-phantom-columns scanner can resolve it): enough for the reviewer
// preview + the same bookability gates the commit path enforces
// (requireSettled batch booking in skatteverket/lib/skattekonto-booking.ts).

interface SkattekontoStageRow {
  id: string
  transaktionsdatum: string
  transaktionstext: string
  belopp_skatteverket: number | string
  status: string
  is_ignored: boolean | null
  journal_entry_id: string | null
}

/**
 * The verifikat approving a skattekonto row posts, as the approval card shows
 * it: the executor's own builder (buildSkattekontoEntry) fed the stage-time
 * rule match, so the reviewer reads accounts and amounts, not field names
 * (crm#1104).
 */
function skattekontoBuiltEntry(
  row: SkattekontoStageRow,
  suggestion: SkattekontoBookingSuggestion,
  skattekontoAccount: SkattekontoLedgerAccount,
) {
  return buildSkattekontoEntry(
    row,
    {
      account: suggestion.account,
      label: suggestion.label ?? row.transaktionstext,
      ...(suggestion.ore_rounding ? { oreRounding: suggestion.ore_rounding } : {}),
      ...(suggestion.rot_rut_payout ? { rotRutPayout: suggestion.rot_rut_payout.leg } : {}),
    },
    skattekontoAccount,
  )
}

function skattekontoEntryPreview(
  row: SkattekontoStageRow,
  suggestion: SkattekontoBookingSuggestion,
  skattekontoAccount: SkattekontoLedgerAccount,
): EntryPreview {
  return toEntryPreview(skattekontoBuiltEntry(row, suggestion, skattekontoAccount))
}

/**
 * Open skattekonto rows dated before history_start: the 1630 IB carries
 * them, so no bridge line, count or opening difference holds them, and Att
 * göra leaves them out by the same reading (crm#1153, crm#1155, crm#2010).
 * Both reconciliation reads say so with the same block, so an agent that
 * sees 0 open rows on the bridge learns where the rest are and that they
 * need nothing.
 */
/**
 * The next call when every pair of a skattekonto reconcile_match was refused
 * for one reason an agent cannot act on from the code alone (crm#1846: a
 * wrong-way pair was retried with allow_remainder, and a verifikat held by a
 * row the open lists do not show read as a contradiction).
 */
function skattekontoSkipRemediation(
  accountKey: string,
  code: string | null,
  first: SkippedPair | undefined,
): { description: string; tool: string; args: Record<string, unknown> } | undefined {
  if (accountKey !== 'skattekonto' || !first) return undefined
  if (code === 'WRONG_DIRECTION') {
    return {
      description:
        'Do not retry this pair, with or without allow_remainder: the row and the verifikat move the skattekonto account in opposite directions, so they are not the same event. A negative row (money out of the skattekonto) needs a verifikat that credits the account, a positive row one that debits it. Pick the verifikat from bucket unmatched_ledger whose amount has the sign of the row, or book the row with gnubok_book_skattekonto_rows when the event is not in the ledger.',
      tool: 'gnubok_list_reconciliation_items',
      args: { account_key: accountKey, bucket: 'unmatched_ledger' },
    }
  }
  const holders = first.linked_external_ids ?? []
  if (code === 'ALREADY_LINKED' && holders.length > 0) {
    return {
      description:
        'The verifikat is held by the rows in linked_external_ids (named in the message). A holder can be missing from unmatched_external and matched: an upcoming row, or one dated after the fetched saldo; gnubok_list_reconciliation_items then shows held_by_uncounted_rows on the verifikat in unmatched_ledger. When the holder is the wrong row (for example an upcoming copy of the event you are linking), undo its link with gnubok_reconcile_unmatch, one call per row, then send the pair again. When the holder is right, the rows you sent belong to another verifikat.',
      tool: 'gnubok_reconcile_unmatch',
      args: { account_key: accountKey, external_id: holders[0] },
    }
  }
  return undefined
}

function skattekontoBeforeHistoryBlock(summary: {
  count: number
  total: number
  history_start: string | null
}): { count: number; total: number; history_start: string | null; note: string } {
  return {
    ...summary,
    note:
      `${summary.count} open Skatteverket row(s) are dated before history_start ${summary.history_start ?? ''}: the ingående balans on 1630 carries that time, so they are in no bridge line, count or opening difference, and Att göra (Bokför skattekontohändelser) does not count them. ` +
      'They need no action: do not book, link or ignore them to clear a list. List them with gnubok_list_reconciliation_items, account_key "skattekonto", bucket "before_history". ' +
      'When skattekonto.opening_difference is not 0, the ingående balans on 1630 disagrees with Skatteverket at that date: that is the bridge line Ingående skillnad, to settle with the user.',
  }
}

/**
 * Verifikat on a bank account dated before the first day the bank side
 * covers (bank.history_start, crm#1221): no bank row can match them, so the
 * comparison starts at history_start. Both reconciliation reads say so with
 * this block, so an agent never books or matches them to clear a difference.
 */
function bankBeforeHistoryBlock(summary: {
  count: number
  total: number
  history_start: string | null
}): { count: number; total: number; history_start: string | null; note: string } {
  return {
    ...summary,
    note:
      `${summary.count} verifikat on this bank account are dated before history_start ${summary.history_start ?? ''}, the first day the bank feed or an imported bank file covers: no bank row can match them, so they are in no bridge line, count or unexplained_difference. ` +
      'List them with gnubok_list_reconciliation_items, bucket "before_history". Do not book, match or ignore anything for them. ' +
      'To reconcile that time as well, import the older bank history (a bank file, or gnubok_create_transactions): history_start then moves earlier and they become matchable. ' +
      'bank.opening_difference, when not null, compares the ledger balance before history_start with the bank\'s saldo that day.',
  }
}

/**
 * gnubok_ignore_transaction for an id that is no bank transaction: the
 * "ignore" action gnubok_list_reconciliation_items offers on a skattekonto
 * row (crm#1178: an enskild firma's skattekonto holds the owner's private
 * tax from before the firm started). The commit runs setItemIgnored, the
 * function the Avstämning page and the v1 ignore route call, so the three
 * doors refuse the same rows. Staged with the qualified
 * skattekonto_transaction_id, never as a transaction_id.
 */
async function stageSkattekontoRowIgnore(input: {
  args: Record<string, unknown>
  companyId: string
  userId: string
  supabase: SupabaseClient
  actor: ActorContext | undefined
  rowId: string
  restore: boolean
}): Promise<unknown> {
  const { args, companyId, userId, supabase, actor, rowId, restore } = input
  const { data: row, error } = await supabase
    .from('skattekonto_transactions')
    .select('id, transaktionsdatum, transaktionstext, belopp_skatteverket, journal_entry_id, is_ignored')
    .eq('id', rowId)
    .eq('company_id', companyId)
    .maybeSingle<{
      id: string
      transaktionsdatum: string
      transaktionstext: string
      belopp_skatteverket: number | string
      journal_entry_id: string | null
      is_ignored: boolean | null
    }>()
  if (error) throw dbError(error)
  if (!row) {
    throw codedRefusal(
      'NOT_FOUND',
      'No bank transaction and no skattekonto row with this id in the company. Copy transaction_id from gnubok_list_uncategorized_transactions, or item_id from gnubok_list_reconciliation_items.',
    )
  }
  // The rule setSkattekontoRowIgnored applies at commit: an ignored row never
  // carries a link (DB CHECK), so a linked row is unlinked first.
  if (!restore && row.journal_entry_id) {
    throw codedRefusal(
      'TX_IGNORE_ALREADY_BOOKED',
      'The skattekonto row is linked to a verifikat. Unlink it with gnubok_reconcile_unmatch (account_key "skattekonto", external_id = this id) before ignoring it.',
      {
        description: 'A linked skattekonto row cannot be ignored: unlink it first, then ignore.',
        tool: 'gnubok_reconcile_unmatch',
        args: { account_key: 'skattekonto', external_id: row.id },
      },
    )
  }
  const label = row.transaktionstext || row.id
  return stage({
    supabase,
    companyId,
    userId,
    type: 'ignore_transaction',
    title: restore ? `Återställ ignorerad skattekontohändelse: ${label}` : `Ignorera skattekontohändelse: ${label}`,
    params: { skattekonto_transaction_id: row.id, ignored: !restore },
    preview: {
      skattekonto_transaction_id: row.id,
      account_key: 'skattekonto',
      transaction_description: label,
      amount: Number(row.belopp_skatteverket),
      currency: 'SEK',
      date: row.transaktionsdatum,
      currently_ignored: Boolean(row.is_ignored),
      will_be_ignored: !restore,
      already_in_state: Boolean(row.is_ignored) === !restore,
      writes_verifikat: false,
      period_lock_applies: false,
    },
    actor,
    next: {
      description: restore
        ? 'After approval the row is open on the skattekonto again: link it with gnubok_reconcile_match or book it.'
        : 'After approval the row is on the bridge\'s "Ignorerade händelser" line and leaves the open rows.',
      tool: 'gnubok_get_reconciliation_status',
      args: { account_key: 'skattekonto' },
    },
    ...stagingOptions(args),
    dateForPeriodCheck: row.transaktionsdatum,
  })
}

const SKATTEKONTO_TWIN_TAIL =
  'A key without the reconciliation:write scope cannot call gnubok_reconcile_match: the user links the row with Koppla on the Skattekonto page in Accounted. Book it anyway (allow_duplicate=true, or allow_duplicate_ids for the batch tool, with the reason in duplicate_reason) only when the user confirms the event really happened twice.'

/**
 * The event of a skattekonto row is already in the ledger (a verifikat the
 * match flow would link, e.g. one imported by SIE). Coded so an agent links
 * instead of retrying; the Swedish text names the verifikat.
 */
function skattekontoLedgerTwinRefusal(
  rowId: string,
  twins: SkattekontoLedgerTwin[],
  skattekontoAccount: SkattekontoLedgerAccount,
  rowCount = 1,
): Error {
  const ids = twins.map((t) => t.journal_entry_id)
  // A combined twin settles the verifikat only together with other open rows
  // (of the same day or the days around it): the link must carry all of
  // them, or it is refused.
  const companionIds = (twins[0]?.combined_with ?? []).map((c) => c.id)
  const lead = rowCount > 1 ? `Alla ${rowCount} rader finns redan i bokföringen. Första raden: ` : ''
  const message = `${lead}${ledgerTwinMessage(twins, { account: skattekontoAccount })}`
  return codedRefusal('SKATTEKONTO_BOOK_LEDGER_TWIN_EXISTS', message, {
    description:
      ids.length > 1
        ? `Ask the user which of the named verifikat is the ledger side of this event and link the row to it with gnubok_reconcile_match (account_key "skattekonto"). ${SKATTEKONTO_TWIN_TAIL}`
        : companionIds.length > 0
          ? `Link the row, together with the ${companionIds.length} other open row(s) that the verifikat also carries, to the named verifikat instead of booking it: gnubok_reconcile_match with account_key "skattekonto" and one pair { external_ids: [row id, ...companion ids], journal_entry_ids: [verifikat id] } (see args). ${SKATTEKONTO_TWIN_TAIL}`
          : `Link the row to the named verifikat instead of booking it: gnubok_reconcile_match with account_key "skattekonto" and pairs [{ external_ids: [row id], journal_entry_ids: [verifikat id] }]. ${SKATTEKONTO_TWIN_TAIL}`,
    tool: 'gnubok_reconcile_match',
    args: {
      account_key: 'skattekonto',
      pairs: [{ external_ids: [rowId, ...companionIds], journal_entry_ids: ids.slice(0, 1) }],
    },
  })
}

/**
 * The rows are already in the ledger inside unlinked verifikat on 1630 (a
 * summarised year-end or month-end verifikat, crm#1043): no verifikat
 * carries any one of them exactly, the reconciliation's arithmetic shows
 * they are covered. Coded so an agent links instead of booking them twice;
 * the args are the link to make, with allow_remainder for what the verifikat
 * holds beyond these rows.
 */
function skattekontoLedgerCoverRefusal(
  rowIds: string[],
  cover: SkattekontoLedgerCoverInfo,
  rowCount = rowIds.length,
): Error {
  const lead = rowCount > 1 ? `Alla ${rowCount} rader ser redan ut att vara bokförda. ` : ''
  const target = cover.entries[0]?.journal_entry_id
  if (cover.kind === 'planned_link' && target) {
    // The ledger plan names the one verifikat and every row it holds: the
    // exact link, no remainder, is the args.
    return codedRefusal('SKATTEKONTO_BOOK_LEDGER_COVER_EXISTS', `${lead}${ledgerCoverMessage(cover)}`, {
      description: `Do not book. The named verifikat holds exactly this row and the other rows in args (bucket proposed): link them as one pair with gnubok_reconcile_match, or every such proposal with use_proposals: true, dry_run first. ${SKATTEKONTO_TWIN_TAIL}`,
      tool: 'gnubok_reconcile_match',
      args: {
        account_key: 'skattekonto',
        pairs: [{ external_ids: cover.event_ids ?? rowIds.slice(0, 50), journal_entry_ids: [target] }],
      },
    })
  }
  return codedRefusal('SKATTEKONTO_BOOK_LEDGER_COVER_EXISTS', `${lead}${ledgerCoverMessage(cover)}`, {
    description:
      `Do not book. Rows that one verifikat holds exactly are already proposed (bucket proposed, a group named in external_ids): gnubok_reconcile_match with use_proposals: true links them all, dry_run first. Link the other open rows up to ${cover.through_date} to the unlinked verifikat on ${cover.account_number} that already hold them (gnubok_list_reconciliation_items, account_key "skattekonto": rows with covered_by_ledger in unmatched_external, the verifikat in unmatched_ledger): gnubok_reconcile_match with pairs of at most 50 rows per verifikat, and allow_remainder: true on a pair whose rows do not sum to the verifikat (a summarised verifikat: the rest stays on it as its remainder). With several verifikat ask the user which rows belong to which. ${SKATTEKONTO_TWIN_TAIL}`,
    tool: 'gnubok_reconcile_match',
    args: {
      account_key: 'skattekonto',
      pairs: [
        {
          external_ids: rowIds.slice(0, 50),
          journal_entry_ids: target ? [target] : [],
          allow_remainder: true,
        },
      ],
    },
  })
}

/**
 * The event is already in the ledger without the skattekonto: a bank
 * verifikat with no line on the skattekonto account books the row's counter
 * line in its month (PH 171). Nothing to link (the verifikat has no
 * skattekonto line), so the way out is to leave the row unbooked: ignore it.
 */
function skattekontoLedgerDirectRefusal(
  rowId: string,
  holders: SkattekontoLedgerTwin[],
  counter: SkattekontoCounterLine,
  skattekontoAccount: SkattekontoLedgerAccount,
  rowCount = 1,
): Error {
  const lead = rowCount > 1 ? `Alla ${rowCount} rader finns redan i bokföringen. Första raden: ` : ''
  return codedRefusal(
    'SKATTEKONTO_BOOK_LEDGER_DIRECT_EXISTS',
    `${lead}${ledgerDirectMessage(holders, counter, skattekontoAccount)}`,
    {
      description: `Do not book. The named verifikat already books this event straight from the bank, without ${skattekontoAccount}, so there is nothing to link: ignore the row with gnubok_ignore_transaction (args), together with the month's other rows the same verifikat holds, or have the user correct the verifikat to go via ${skattekontoAccount} and then link. Book anyway (allow_duplicate=true, or allow_duplicate_ids for the batch tool, with the reason in duplicate_reason) only when the user confirms the event is really missing from the ledger.`,
      tool: 'gnubok_ignore_transaction',
      args: { transaction_id: rowId },
    },
  )
}

/** Reviewer warning when a staged booking was told to book a row a bank verifikat already books without the skattekonto. */
function skattekontoDirectNote(holders: SkattekontoLedgerTwin[], skattekontoAccount: SkattekontoLedgerAccount): string {
  const refs = holders
    .slice(0, 5)
    .map((t) => (t.voucher_number ? formatVoucher(t) : `draft ${t.entry_date}`))
    .join(', ')
  return `DUPLICATE_OVERRIDE: verifikat ${refs} already book this event from the bank without ${skattekontoAccount}. Approving books it a second time; approve only if the event is really missing from the ledger, otherwise reject and ignore the row.`
}

/** Reviewer warning when a staged booking was told to book rows the ledger already covers. */
function skattekontoCoverNote(cover: SkattekontoLedgerCoverInfo): string {
  const refs = cover.entries
    .slice(0, 5)
    .map((t) => (t.voucher_number ? formatVoucher(t) : `no number ${t.entry_date}`))
    .join(', ')
  const held =
    cover.kind === 'planned_link'
      ? `unlinked verifikat ${refs} on ${cover.account_number} already holds this row exactly, with ${cover.event_count - 1} other open row(s)`
      : `unlinked verifikat on ${cover.account_number} (${refs}) already hold the open rows up to ${cover.through_date}`
  return `DUPLICATE_OVERRIDE: ${held}. Approving books them a second time; approve only if the events really are missing from the ledger, otherwise reject and link the rows instead.`
}

/** Reviewer warning when a staged booking was told to ignore a ledger twin. */
function skattekontoDuplicateNote(twins: SkattekontoLedgerTwin[], skattekontoAccount: SkattekontoLedgerAccount): string {
  const refs = twins
    .slice(0, 5)
    .map((t) => (t.voucher_number ? formatVoucher(t) : `draft ${t.entry_date}`))
    .join(', ')
  return `DUPLICATE_OVERRIDE: verifikat ${refs} already carry this event on ${skattekontoAccount}. Approving books it a second time; approve only if the event really happened twice, otherwise reject and link the row instead.`
}

/**
 * Count ERROR-level findings in a /kontrollera response body.
 *
 * Skatteverket wraps them in `kontrollResultat.resultat` (Momsdeklaration
 * v1.0.24 RAML, note SKV's mixed casing); the bare `resultat` fallback exists
 * so an unwrapped body can never silently read as "no errors". Same convention
 * as the shipped filing chain (skatteverket/lib/vat-submit.ts).
 *
 * A green count here means the ARITHMETIC is consistent. It is not a statement
 * about whether the declaration reflects the books: see the module header of
 * lib/reports/vat-declaration-checks.ts.
 */
function countSkvKontrollErrors(body: unknown): number {
  if (!body || typeof body !== 'object') return 0
  const root = body as Record<string, unknown>
  const wrapped = root.kontrollResultat as Record<string, unknown> | undefined
  const findings = (wrapped?.resultat ?? root.resultat) as unknown
  const list = Array.isArray(findings) ? findings : []
  const errors = list.filter(
    (f) => (f as { status?: string } | null)?.status === 'ERROR'
  ).length
  if (errors > 0) return errors
  // A top-level status of ERROR with no itemised findings still means rejected.
  const status = (wrapped?.status ?? root.status) as string | undefined
  return status === 'ERROR' ? 1 : 0
}

/** YYYYMM → last day of that month as yyyy-MM-dd (for dateForPeriodCheck). */
function skvPeriodToEndDate(redovisningsperiod: string): string {
  const year = Number(redovisningsperiod.slice(0, 4))
  const month = Number(redovisningsperiod.slice(4, 6))
  const lastDay = new Date(year, month, 0).getDate()
  return `${year}-${String(month).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`
}

// ── Typed refusals for lookups and links ──────────────────────
//
// A plain `throw new Error(text)` reaches the agent as UNKNOWN_ERROR, "Något
// gick fel. Försök igen.": retry advice for a call that cannot succeed.

/**
 * Whether a lookup by id failed only because no row can match: `.single()`
 * found none (PGRST116) or the id is not a UUID at all (22P02). Any other
 * database failure is thrown as itself (dbError keeps the SQLSTATE), so a
 * statement timeout stays TRANSIENT_ERROR instead of reading as a wrong id.
 */
function isLookupMiss(error: { code?: string | null } | null): boolean {
  return !error || error.code === 'PGRST116' || error.code === '22P02'
}

/**
 * Supabase Storage's refusal of an object over the bucket's file_size_limit:
 * HTTP 413, "The object exceeded the maximum allowed size".
 */
function isStorageObjectTooLarge(error: unknown): boolean {
  const e = error as { status?: unknown; statusCode?: unknown; message?: unknown }
  return e.status === 413 || e.statusCode === '413' || /exceeded the maximum allowed size/i.test(String(e.message ?? ''))
}

/**
 * NOT_FOUND for a document_attachments id, naming the id the agent sent and
 * where a document id comes from. An id that is no UUID can be no document's:
 * one agent sent its chat client's own file id ("file_...") 37 times against
 * the bare sentence, never learning that the file was not in Accounted.
 */
function documentNotFound(documentId: string): Error {
  const sources =
    'A document id is the UUID Accounted gave the file: document_id from gnubok_list_inbox_items or gnubok_list_unmatched_documents, the id in a document:<uuid> record_ref (gnubok_list_records, gnubok_search_records), or the result of an upload.'
  if (!isUuid(String(documentId).trim())) {
    return codedRefusal(
      'NOT_FOUND',
      `Document not found: ${JSON.stringify(documentId)} is not a document id. ${sources} A file that exists only in this conversation is not in Accounted yet.`,
      {
        description: 'To put a file from this conversation into Accounted, upload it: gnubok_create_document_upload returns where to send the bytes, then gnubok_complete_document_upload gives its document id.',
        tool: 'gnubok_create_document_upload',
      },
    )
  }
  return codedRefusal('NOT_FOUND', `Document not found: no document with id ${documentId} in this company. ${sources}`)
}

/**
 * The document behind each inbox item id among `ids`. An upload's document
 * shares its inbox item's id, but a mail or WhatsApp arrival gives its
 * document an id of its own, so an agent that read ids off
 * gnubok_list_inbox_items sent inbox item ids as document_id and every
 * forwarded receipt missed as document_not_found (Kvittojakten run,
 * 2026-10-29). Called with the ids no document answered to; an id that is
 * neither stays a miss.
 */
async function documentIdsForInboxItems(
  supabase: SupabaseClient,
  companyId: string,
  ids: string[],
): Promise<Map<string, string>> {
  if (ids.length === 0) return new Map()
  const { data, error } = await supabase
    .from('invoice_inbox_items')
    .select('id, document_id')
    .eq('company_id', companyId)
    .in('id', ids)
    .not('document_id', 'is', null)
  if (error) {
    if (isLookupMiss(error)) return new Map()
    throw dbError(error)
  }
  const rows = (data ?? []) as Array<{ id: string; document_id: string }>
  return new Map(rows.filter((r) => r.document_id !== r.id).map((r) => [r.id, r.document_id]))
}

/** NOT_FOUND for the operation id sent to approve or reject. */
function pendingOperationNotFound(operationId: string): Error {
  return codedRefusal(
    'NOT_FOUND',
    `Pending operation not found: no operation with id ${operationId}. List open ones with gnubok_list_pending_operations.`,
  )
}

/** How many operations one gnubok_approve_pending_operation call settles by id. */
const MAX_APPROVE_OPERATION_IDS = 50

/** operation_ids as the approve tool reads it: 1 to 50 UUIDs, repeats dropped. */
function parseApproveOperationIds(value: unknown): string[] {
  if (!Array.isArray(value) || value.length === 0) {
    throw badArgument('operation_ids', 'operation_ids must be a non-empty array of operation ids', 'Ange minst ett operation_id.')
  }
  if (value.length > MAX_APPROVE_OPERATION_IDS) {
    throw badArgument(
      'operation_ids',
      `operation_ids takes at most ${MAX_APPROVE_OPERATION_IDS} ids; approve the rest in another call`,
      `Högst ${MAX_APPROVE_OPERATION_IDS} åt gången.`,
    )
  }
  const invalid = value.find((id) => typeof id !== 'string' || !UUID_RE.test(id))
  if (invalid !== undefined) {
    throw badArgument('operation_ids', `operation_ids must hold operation UUIDs; got ${JSON.stringify(invalid)}`, 'Ogiltigt operation_id.')
  }
  return [...new Set(value as string[])]
}

/**
 * A voucher-link validator's refusal: its registry code on `.code` (it used
 * to ride in the message text only), the registry's English and the details
 * the validator names (amounts, currencies, status).
 */
function voucherLinkRefusal(failure: { code: string; details?: Record<string, unknown> }): Error {
  const text = [
    `Cannot link voucher: ${failure.code}.`,
    getErrorEntry(failure.code)?.message_en,
    failure.details ? `Details: ${JSON.stringify(failure.details)}` : undefined,
  ]
  return codedRefusal(failure.code, text.filter(Boolean).join(' '))
}

// ── Journal entry reference resolution ────────────────────────

/**
 * Resolve a journal entry reference to a journal_entries.id UUID.
 *
 * Accepts either a raw UUID (returned as-is) or a voucher reference like
 * "A-113" / "A113" / "A/113" (resolved by voucher_series + voucher_number
 * scoped to the company).
 *
 * Voucher refs are the preferred input shape for LLM-driven callers: short,
 * semantically meaningful, and resistant to UUID hallucination: a failure
 * mode where the agent reproduces the first 8 hex chars correctly but
 * fabricates the remaining 24, so a downstream lookup rejects the ID even
 * though the entry exists.
 */
async function resolveJournalEntryRef(
  supabase: SupabaseClient,
  companyId: string,
  ref: string
): Promise<string> {
  const trimmed = ref.trim()

  // UUIDs pass through. If the UUID was hallucinated, the caller's own
  // lookup surfaces the "not found" diagnostic with the supplied value.
  if (UUID_RE.test(trimmed)) {
    return trimmed
  }

  // Voucher ref: letters (series) + optional separator + digits (number).
  // Both callers (correct_entry, reverse_journal_entry) take it as entry_id.
  const match = trimmed.match(/^([A-Za-z]+)\s*[-:/ ]?\s*(\d+)$/)
  if (!match) {
    throw fieldValidationError('Invalid arguments', [{
      field: 'entry_id',
      en: `Could not parse entry reference "${ref}". Expected a UUID or a voucher ref like "A-113".`,
      sv: `Kunde inte tolka "${ref}": ange verifikationens id (UUID) eller en verifikationsreferens som "A-113".`,
    }])
  }
  const series = match[1].toUpperCase()
  const number = parseInt(match[2], 10)

  const { data, error } = await supabase
    .from('journal_entries')
    .select('id, entry_date, description')
    .eq('company_id', companyId)
    .eq('voucher_series', series)
    .eq('voucher_number', number)
    .order('entry_date', { ascending: false })

  if (error) {
    throw dbError(error, `Database error resolving voucher "${series}-${number}"`)
  }

  const matches = (data ?? []) as Array<{ id: string; entry_date: string; description: string }>

  if (matches.length === 0) {
    throw codedRefusal(
      'NOT_FOUND',
      `No journal entry found for voucher "${series}-${number}" in this company. ` +
      `Verify the series and number, or supply the full UUID.`
    )
  }

  // Voucher numbers reset per fiscal period. The same (series, number) pair
  // can therefore appear in multiple years: refuse to guess. The candidates
  // stay in message_en: they are how the agent picks the id to send instead.
  if (matches.length > 1) {
    const summary = matches
      .map((m) => `${m.entry_date} "${m.description}" (id=${m.id})`)
      .join('; ')
    throw fieldValidationError('Invalid arguments', [{
      field: 'entry_id',
      en:
        `Voucher "${series}-${number}" matches multiple entries across fiscal periods: ${summary}. ` +
        `Supply the specific UUID instead.`,
      sv: `Verifikation ${series}-${number} finns i flera räkenskapsår: ange verifikationens id (UUID) i stället.`,
    }])
  }

  return matches[0].id
}

// ── Document links into locked periods ───────────────────────

/**
 * A fiscal period holding rows gnubok_link_documents_to_vouchers leaves
 * unstaged because enforce_period_lock_documents refuses the link there.
 * reopen_tool is the way back for that state: unlock a locked year, reopen a
 * year marked closed in the previous system (klarmarkerat); a year closed by
 * a year-end run here has none: only the company owner reopens it, in the
 * app, and no tool does.
 */
interface LockedLinkPeriod {
  fiscal_period_id: string
  fiscal_year: number
  status: 'locked' | 'closed'
  row_count: number
  reopen_tool: 'gnubok_unlock_period' | 'gnubok_reopen_fiscal_period_external' | null
}

function lockedLinkPeriod(
  period: { id: string; is_closed: boolean; closed_externally: boolean | null; closing_entry_id: string | null },
  fiscalYear: number,
  rowCount: number,
): LockedLinkPeriod {
  const reopenTool = !period.is_closed
    ? 'gnubok_unlock_period'
    : period.closed_externally && !period.closing_entry_id
      ? 'gnubok_reopen_fiscal_period_external'
      : null
  return {
    fiscal_period_id: period.id,
    fiscal_year: fiscalYear,
    status: period.is_closed ? 'closed' : 'locked',
    row_count: rowCount,
    reopen_tool: reopenTool,
  }
}

/**
 * Staging refusal for a batch with nothing left to stage when rows sit in
 * locked or closed periods. Staging such a batch only moved the refusal to
 * approval: feedback seq 754875 previewed 142 of 142 as matched, and every row
 * was refused after approval because the years had been klarmarkerade (closed
 * and locked) 30 minutes before staging.
 */
/**
 * What a refused link says when the document belongs to another verifikat
 * and this one needs the same underlag (crm#1207: a rättelse resting on the
 * original's invoice; crm#1171 item 9: one bank statement, several fees).
 * Re-uploading the file is no way out: the signed-URL upload returns the
 * existing document for identical bytes, and an agent then changed a byte to
 * get a new id. copy: true archives a byte-identical copy at approval instead.
 */
function sharedUnderlagCopyHint(): string {
  return (
    'If this verifikat needs the same underlag too (a statement covering several fees, a correction resting on the ' +
    'original\'s invoice), stage this link again with copy: true: approval archives a byte-identical copy on this ' +
    'verifikat and the original stays where it is. Do not re-upload or alter the file.'
  )
}

/**
 * The approver's note on a staged copy of a receipt or an invoice: the same
 * one on two verifikat is more often one purchase booked twice than one
 * underlag backing two events (an invoice paid in parts is the exception).
 */
const DOUBLE_BOOKING_DOC_TYPES = new Set(['receipt', 'supplier_invoice', 'customer_invoice'])
function copyDoubleBookingNote(docType: string | null | undefined): string | null {
  if (!docType || !DOUBLE_BOOKING_DOC_TYPES.has(docType)) return null
  return (
    'Underlaget är ett kvitto eller en faktura som redan styrker en annan verifikation. Samma köp kan då bli bokfört två ' +
    'gånger: godkänn kopian bara om underlaget verkligen styrker båda, till exempel en faktura som betalas i flera delar.'
  )
}

function lockedPeriodLinkError(total: number, periods: LockedLinkPeriod[], otherMisses: unknown[]): Error {
  const rows = (n: number) => `${n} ${n === 1 ? 'row' : 'rows'}`
  const lockedRows = periods.reduce((sum, p) => sum + p.row_count, 0)
  const perPeriod = periods.map((p) => {
    const state = p.reopen_tool === 'gnubok_unlock_period'
      ? 'is locked: unlock it with gnubok_unlock_period'
      : p.reopen_tool === 'gnubok_reopen_fiscal_period_external'
        ? 'is marked closed in the previous system: reopen it with gnubok_reopen_fiscal_period_external'
        : 'was closed by a year-end run here: only the company owner can reopen it, in the app (Inställningar → Bokföring → Räkenskapsår), while its årsredovisning is not signed, adopted or filed'
    return `fiscal_year ${p.fiscal_year} (fiscal_period_id ${p.fiscal_period_id}, ${rows(p.row_count)}) ${state}.`
  })
  const reopenable = periods.filter((p) => p.reopen_tool !== null)
  const message =
    `No links staged: ${lockedRows} of ${total} rows target verifikat in a locked or closed fiscal period, ` +
    `where the database refuses to attach documents. ${perPeriod.join(' ')}` +
    (reopenable.length > 0 ? ' Then stage those links again, and lock or klarmarkera the year again once they are linked.' : '') +
    (otherMisses.length > 0 ? ` ${rows(otherMisses.length)} more did not resolve either; first: ${JSON.stringify(otherMisses[0])}` : '')
  const first = reopenable[0]
  return Object.assign(new Error(message), {
    code: 'DOC_UPLOAD_PERIOD_LOCKED',
    remediation: {
      description:
        'Reopen the year, stage the links again, then lock or klarmarkera it again: gnubok_reopen_fiscal_period_external ' +
        'for a year marked closed in the previous system, gnubok_unlock_period for a locked year that is not closed. ' +
        'A year closed by a year-end run here is reopened only by the company owner in the app (Inställningar → Bokföring → ' +
        'Räkenskapsår) while its årsredovisning is not signed, adopted or filed; there is no API or MCP door. A year that ' +
        'stays closed keeps the document archived unlinked.',
      ...(first ? { tool: first.reopen_tool } : {}),
      ...(first && reopenable.length === 1 ? { args: { fiscal_period_id: first.fiscal_period_id } } : {}),
    },
  })
}

/**
 * The refusal for a gnubok_link_documents_to_vouchers call where no row
 * resolved. It was a plain Error, so the agent read UNKNOWN_ERROR, "Något gick
 * fel. Försök igen.", for a call no retry fixes: 16 calls in 30 days, 10 with
 * every document already on another verifikat, 6 naming a document or
 * verifikat that does not exist. The code names what the caller must change,
 * ids that resolve to nothing first; the message counts every status and
 * shows the first row of each.
 */
const UNRESOLVED_LINK_CLASSES: ReadonlyArray<{ code: string; statuses: readonly string[]; hint: string }> = [
  {
    code: 'NOT_FOUND',
    statuses: ['document_not_found', 'voucher_not_found', 'unknown_fiscal_year'],
    hint:
      'document_not_found: the id is no document or inbox item of this company (gnubok_list_unmatched_documents lists them). ' +
      'voucher_not_found, unknown_fiscal_year: no verifikat with that number in that fiscal year; name it by journal_entry_id ' +
      '(gnubok_list_verifikat_without_documents).',
  },
  {
    code: 'DOC_LINK_ALREADY_LINKED',
    statuses: ['already_linked'],
    hint:
      'already_linked: the document is on the verifikat in linked_journal_entry_id and a link never moves (BFL 5 kap 6 §). ' +
      'If this verifikat needs the same underlag too, send the row again with copy: true: approval archives a byte-identical ' +
      'copy. Do not re-upload or alter the file.',
  },
  {
    code: 'DOC_LINK_PROPOSED_ELSEWHERE',
    statuses: ['proposed_elsewhere'],
    hint:
      'proposed_elsewhere: the waiting operation in conflicting_operation_id links the document to another verifikat; ' +
      'reject it first, or send the row with copy: true if both verifikat need it.',
  },
  {
    code: 'VALIDATION_ERROR',
    statuses: ['ambiguous_fiscal_year', 'duplicate_in_batch'],
    hint:
      'ambiguous_fiscal_year: more than one fiscal period starts that year; name the verifikat by journal_entry_id. ' +
      'duplicate_in_batch: the same document twice without copy: true.',
  },
]

function noLinksResolvedError(total: number, results: ReadonlyArray<{ status: string }>): Error {
  const firstByStatus = new Map<string, { row: unknown; count: number }>()
  for (const r of results) {
    const seen = firstByStatus.get(r.status)
    if (seen) seen.count += 1
    else firstByStatus.set(r.status, { row: r, count: 1 })
  }
  const present = UNRESOLVED_LINK_CLASSES.filter((c) => c.statuses.some((s) => firstByStatus.has(s)))
  const counts = [...firstByStatus].map(([status, { count }]) => `${status} ${count}`).join(', ')
  const firsts = [...firstByStatus.values()].map(({ row }) => JSON.stringify(row)).join('; ')
  return codedRefusal(
    present[0]?.code ?? 'VALIDATION_ERROR',
    `No links resolved: 0/${total} rows matched a document and a verifikat that can take it (${counts}). First of each: ${firsts}`,
    { description: present.map((c) => c.hint).join(' ') || 'Check each row against its status.' },
  )
}

// ── Shared categorization logic ──────────────────────────────

// ── Lock-period staging guard ────────────────────────────────────────────────
//
// The staging pre-check runs the exact same countUnbookedInPeriod the commit
// path (lockPeriod) enforces, imported from period-service so the two legal
// guards cannot drift apart. See the DECISIONS.md archive 2026-07-26 lock-guard entry
// for the predicate semantics.

/**
 * A categorize dry-run refusal as the error the agent reads. Three keep the
 * wording agents act on: the row is not a bank transaction (a skattekonto row
 * books with its own tool), it is already booked (correct or reverse the
 * verifikat instead), and a likely double-booking (link to the existing
 * verifikat, or rerun with allow_duplicate). Every other refusal carries its
 * registry code and the service's own sentence.
 */
function categorizeStagingRefusal(refusal: CategorizeRefusal, transactionId: string): Error {
  if (refusal.code === 'TX_CATEGORIZE_TX_NOT_FOUND') {
    // Only bank rows live in `transactions`. A skattekonto_transactions id
    // lands here as NOT_FOUND and agents concluded the row could not be
    // booked (feedback seq 382367): name the right tool.
    return new OperationError(refusal.code, {
      messageSv:
        'Transaction not found. Check the transaction_id is correct. ' +
        'A skattekonto row (Skatteverket tax account: ränta, avgift, preliminärskatt, moms) is not a bank transaction: book it with gnubok_book_skattekonto_row or gnubok_book_skattekonto_rows (find them via gnubok_search_tools "skattekonto").',
    })
  }
  if (refusal.code === 'TRANSACTION_ALREADY_CATEGORIZED') {
    const journalEntryId = (refusal.details?.journal_entry_id as string | null | undefined) ?? 'unknown'
    return new OperationError(refusal.code, {
      details: refusal.details,
      messageSv:
        `Transaction is already booked (journal_entry_id ${journalEntryId}); ` +
        'nothing to categorize. Use gnubok_list_uncategorized_transactions to find unbooked ones, ' +
        'or gnubok_correct_entry / gnubok_reverse_journal_entry to change the existing verifikat.',
    })
  }
  if (refusal.code === 'TRANSACTION_BOOK_POSSIBLE_DUPLICATE') {
    const candidate = refusal.details?.candidate as BookedDuplicateCandidate | undefined
    if (candidate) {
      return new OperationError(refusal.code, {
        details: refusal.details,
        messageSv: agentDuplicateMessage(candidate, refusal.transaction?.currency),
      })
    }
  }
  if (refusal.cause instanceof Error && refusal.code === 'TX_MISSING_SEK_VALUE') return refusal.cause
  log.info('categorize staging refused', { transactionId, code: refusal.code })
  return new OperationError(refusal.code, { details: refusal.details, messageSv: refusal.message?.sv })
}

/**
 * A voucher line that names neither debit_amount nor credit_amount is a shape
 * error, not a zero line. `Number(undefined) || 0` silently turned
 * {debit: 500}, {amount, side} and {debitAmount: 500} into 0/0, and the
 * balance check then reported "debits 0 SEK, credits 0 SEK" for four
 * perfectly balanced formats (feedback seq 318571). No host validates
 * inputSchema at runtime, so the guard lives here, and it names the keys it
 * got so the agent can fix the shape in one turn instead of guessing at the
 * amounts. A VALIDATION_ERROR: as a plain error it answered UNKNOWN_ERROR,
 * "try again", in 22 sessions in 30 days.
 */
function assertVoucherLineShape(line: Record<string, unknown>, label: string): void {
  const hasDebit = line.debit_amount !== undefined && line.debit_amount !== null
  const hasCredit = line.credit_amount !== undefined && line.credit_amount !== null
  if (!hasDebit && !hasCredit) {
    const got = Object.keys(line).filter((k) => k !== 'account_number')
    throw badArgument(
      label,
      `${label}: expected debit_amount and/or credit_amount (numbers in SEK)` +
        (got.length ? `; got ${got.join(', ')}` : '; got neither') +
        '. Example: {"account_number":"6110","debit_amount":400}, {"account_number":"1930","credit_amount":400}.',
      'Raden saknar debit_amount och credit_amount (belopp i kronor).',
    )
  }
  for (const key of ['debit_amount', 'credit_amount'] as const) {
    const v = line[key]
    if (v !== undefined && v !== null && !Number.isFinite(Number(v))) {
      throw badArgument(`${label}.${key}`, `${label}.${key} must be a number in SEK; got ${JSON.stringify(v)}`)
    }
  }
}

// ── Output schema helpers ────────────────────────────────────

const PAGINATION_PROPS = {
  count: { type: 'number', description: 'Number of items in this page' },
  total_count: { type: 'number', description: 'Total matching across all pages' },
  has_more: { type: 'boolean' },
  next_offset: { type: 'number', description: 'Offset for the next page (omitted on last page)' },
} as const

// Declared loosely on purpose. Every field here is transmitted once per
// staged-write tool, and there are 58 of them in the default catalog, so a
// character in this constant costs 58 characters of every agent's context.
// `additionalProperties: false` stays: staging.test.ts pins the next hint as a
// closed shape, and a guard whose reason is not in front of me is not a guard
// to loosen for 420 tokens. Only args' redundant `additionalProperties: true`
// went, which is the JSON Schema default anyway.
const NEXT_ACTION_HINT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    description: { type: 'string' },
    tool: { type: 'string' },
    args: { type: 'object' },
    resource: { type: 'string' },
  },
  required: ['description'],
} as const

const STAGED_OPERATION_SCHEMA = {
  type: 'object',
  properties: {
    staged: { type: 'boolean' },
    operation_id: { type: 'string', description: 'Set once persisted' },
    risk_level: { type: 'string', enum: ['low', 'medium', 'high'] },
    actor: { type: 'object' },
    dry_run: { type: 'boolean' },
    idempotency_replay: { type: 'boolean' },
    message: { type: 'string' },
    approve: { type: 'object' },
    preview: { type: 'object' },
    // Shape carried in prose rather than declared: the same three properties
    // spelled out as JSON Schema cost 58x what one sentence costs, and the
    // model reads the sentence either way. Same reason actor/approve/preview
    // above have always been bare objects.
    period_status: {
      type: 'object',
      description: 'Period of the affärshändelse: period_id, status (open|locked|closed), lock_date. Detects a locked period without a round-trip.',
    },
    next: NEXT_ACTION_HINT_SCHEMA,
  },
  required: ['staged', 'risk_level', 'actor', 'message', 'preview'],
} as const

/**
 * Staging writes that have a read-only pre-flight an agent should run first.
 * Surfaced as `_meta.preflight` in tools/list so the preview/validate step is
 * discoverable from the staging tool itself, not just from prose. Keep entries
 * to genuine pre-flights (a tool that returns a verdict/proposal before the
 * irreversible write), not recovery/undo tools.
 */
const TOOL_PREFLIGHT_MAP: Record<string, string> = {
  gnubok_run_year_end: 'gnubok_year_end_readiness',
  gnubok_post_kontantmetod_cutoff: 'gnubok_year_end_readiness',
  gnubok_vat_declaration_submit: 'gnubok_vat_declaration_validate',
  gnubok_post_annual_depreciation: 'gnubok_propose_annual_depreciation',
  gnubok_book_salary_run: 'gnubok_get_salary_run',
  gnubok_reconcile_match: 'gnubok_get_reconciliation_status',
  gnubok_reconcile_signoff: 'gnubok_get_reconciliation_status',
  gnubok_reconcile_residual: 'gnubok_get_reconciliation_status',
  gnubok_split_opening_balances_per_project: 'gnubok_preview_opening_balance_split',
}

/**
 * The DECLARED "stages, never commits" property of a tool: its outputSchema IS
 * the staged-operation envelope (identity, not shape). One predicate, two
 * consumers, so they cannot disagree: deriveToolMeta turns it into the
 * `_meta.requires_approval` contract a client reads, and the gnubok_stage_tool
 * bridge uses it to decide which writes it may carry (issue #2800).
 *
 * Deliberately NOT keyed on annotations. ANNOTATIONS_STAGED_WRITE is worn by
 * tools that commit directly (gnubok_create_transactions inserts rows,
 * gnubok_reject_pending_operation settles one), so the constant's name is not
 * a staging signal, and neither is a tool's own name. A declaration is only a
 * claim: __tests__/staging-behaviour.test.ts executes every declaring tool
 * against a recording client and fails one that writes anywhere but
 * pending_operations, and statically refuses a mutation call in its body.
 */
export function isStagingTool(t: { outputSchema?: Record<string, unknown> }): boolean {
  return t.outputSchema === STAGED_OPERATION_SCHEMA
}

/** The stager's own take-back of a staged operation (lib/pending-operations/withdraw.ts). */
export const WITHDRAW_TOOL_NAME = 'gnubok_withdraw_pending_operation'

/**
 * What the stage bridge carries: every staging tool, and the one write that
 * is staging's inverse. gnubok_withdraw_pending_operation commits directly,
 * but all it can do is close a pending operation the calling connection
 * staged itself, so it stays inside the bridge's promise that nothing reaches
 * the books through it. It is search-only (tools/list has no room), and a
 * client that only knows tools/list has no other way to name it; without the
 * bridge the tool would exist for no connector. Approve and reject are not
 * carried, as before: they settle other people's proposals and keep their own
 * listed name and client permission.
 */
export function ridesStageBridge(t: { name: string; outputSchema?: Record<string, unknown> }): boolean {
  return isStagingTool(t) || t.name === WITHDRAW_TOOL_NAME
}

/**
 * The door a tool call goes through (src/lib/permissions/doors.ts): a
 * generated tool's operation door, else the hand-written tool's
 * (./permission-doors.ts). Read by the permission shadow here and, through
 * the agent tool registry, in the in-app assistant.
 */
export function toolPermissionDoor(t: {
  name: string
  outputSchema?: Record<string, unknown>
  annotations?: { effect?: McpToolEffect; readOnlyHint?: boolean }
}): DoorRule | null {
  return mcpToolDoor(t, { stageable: isStagingTool(t), operation: OPERATION_BY_TOOL.get(t.name) })
}

/**
 * Discovery-time metadata derived from a tool definition, surfaced under `_meta`
 * in tools/list (and gnubok_search_tools detail=full). Lets an agent tell
 * (WITHOUT reading prose) whether a write stages for approval and whether a
 * pre-flight exists. `requires_approval` keys off the staged-operation output
 * schema, the single source of truth for "this write produces a
 * pending_operation you must commit via approve_tool". Returns undefined for
 * tools with no staging contract (reads, direct-commit approve/reject) so we
 * don't bloat the catalog with empty objects.
 */
export function deriveToolMeta(t: { name: string; outputSchema?: Record<string, unknown> }): Record<string, unknown> | undefined {
  if (!isStagingTool(t)) return undefined
  const preflight = TOOL_PREFLIGHT_MAP[t.name]
  return {
    requires_approval: true,
    approve_tool: 'gnubok_approve_pending_operation',
    ...(preflight ? { preflight } : {}),
  }
}

// isDefaultCatalogTool lives in tool-reach.ts (shared with recommended-tools.ts
// without an import cycle); re-exported here so the bench and tests keep
// importing it from the server module.
export { isDefaultCatalogTool } from './tool-reach'

type BridgeKind = 'call_tool' | 'stage_tool'

/**
 * The two listed bridges, keyed by canonical tool name. A Map, not an object
 * literal: the key looked up is the caller-supplied tool name, and `in` or
 * index access on an object would match inherited keys ("constructor",
 * "toString") and treat an arbitrary request as a bridge call.
 */
const BRIDGE_TOOLS: ReadonlyMap<string, BridgeKind> = new Map([
  ['gnubok_call_tool', 'call_tool'],
  ['gnubok_stage_tool', 'stage_tool'],
])

/**
 * The tool a bridge call names. `tool` is the declared parameter; an agent
 * that copies the tools/call shape sends `name`, some `tool_name`, and each
 * was refused "requires a tool argument" (39 sessions in 30 days, none got
 * through). Read in that order, so a call that sends `tool` behaves exactly
 * as before.
 */
function bridgeTargetName(args: Record<string, unknown>): string {
  for (const key of ['tool', 'name', 'tool_name']) {
    const value = args[key]
    if (typeof value === 'string' && value.trim() !== '') return value.trim()
  }
  return ''
}

/**
 * Why a bridge will not carry this target, or null when it will.
 *
 * This decides only WHICH tools a bridge may name. It grants nothing: after it
 * passes, the dispatcher runs the target exactly as a direct call, so the
 * target's scope, argument guard, company routing, viewer-role gate,
 * capability paywall and test-key block all still apply. An unknown target
 * returns null on purpose so it reaches the unknown-tool handler, which lists
 * what exists.
 *
 *   call_tool:  reads, and since 2026-10-18 exactly the writes stage_tool
 *               carries. A client whose copy of tools/list predates
 *               gnubok_stage_tool (listed 2026-09-21) still shows
 *               gnubok_call_tool, and a reconnect did not fetch a new list
 *               (support case 2026-10-18), so the read bridge was the only
 *               name such a client could send a payment proposal through.
 *   stage_tool: a write that declares the staged envelope AND is absent from
 *               tools/list. gnubok_approve_pending_operation declares no staged
 *               envelope, so stage-then-approve can never both ride a bridge.
 *
 * Both refuse a write that commits directly and a listed write (it keeps its
 * own per-tool permission in the client).
 *
 * A refusal that sends the agent to a direct call first checks that the key
 * reaches the target: tools/list hides a tool whose scope the key lacks, so
 * "call it directly by name" was advice the agent could not follow (agent
 * feedback seq 871035, a key without pending_operations:approve trying to
 * reject its own staged operation).
 */
function bridgeRefusalReason(
  bridge: BridgeKind,
  requestedToolName: string,
  target: McpTool | undefined,
  keyScopes: ApiKeyScope[],
  receivedKeys: string[] = [],
): string | null {
  const bridgeName = bridge === 'call_tool' ? 'gnubok_call_tool' : 'gnubok_stage_tool'
  if (!requestedToolName) {
    // Say what came instead: the bare sentence gave nothing to correct.
    const got = receivedKeys.length > 0 ? `got ${receivedKeys.map((key) => `"${key}"`).join(', ')}` : 'got no arguments'
    return `${bridgeName} requires a "tool" argument naming the tool to invoke (${got}). A working call looks like: {"tool": "<tool name>", "arguments": {...}}.`
  }
  if (!target) return null
  const isRead = isReadOnlyTool(target)
  const directCall = (lead: string): string =>
    `${lead} ${directCallAdvice(requestedToolName, target, keyScopes)}`
  if (isRead) {
    return bridge === 'call_tool'
      ? null
      : `${requestedToolName} is read-only: invoke it through gnubok_call_tool, not gnubok_stage_tool.`
  }
  if (!ridesStageBridge(target)) {
    return directCall(
      `${requestedToolName} commits directly instead of staging a pending operation, so ${bridgeName} will not invoke it.`,
    )
  }
  if (isDefaultCatalogTool(target)) {
    const required = TOOL_SCOPE_MAP[target.name]
    if (required && !hasScope(keyScopes, required)) {
      return directCall(`${requestedToolName} is a listed tool, so ${bridgeName} will not carry it.`)
    }
    return `${requestedToolName} is in tools/list: call it directly by name so your client applies that tool's own permission. ${staleToolsListAdvice(requestedToolName)}`
  }
  return null
}

/**
 * The second half of a bridge refusal that points at a direct call: the call
 * itself when the key holds the target's scope, otherwise what the key lacks
 * and where the user does it instead. Approve and reject both need
 * pending_operations:approve; without it the user settles staged operations
 * in the web app at /pending.
 */
function directCallAdvice(requestedToolName: string, target: McpTool, keyScopes: ApiKeyScope[]): string {
  const required = TOOL_SCOPE_MAP[target.name]
  if (!required || hasScope(keyScopes, required)) {
    // A listed tool the agent tried to bridge is often one its client never
    // showed it: the client kept an older tools/list (agent feedback seq
    // 995216). Say what unblocks it instead of only repeating "call it".
    return isDefaultCatalogTool(target)
      ? `Call ${requestedToolName} directly by name. ${staleToolsListAdvice(requestedToolName)}`
      : `Call ${requestedToolName} directly by name.`
  }
  const lacks = `This API key lacks the ${required} scope, so ${requestedToolName} is not in your tools/list and a direct call is refused too.`
  return required === 'pending_operations:approve'
    ? `${lacks} Do not retry: the user approves or rejects pending operations in the web app at /pending (Att göra > Rutin). To take back a proposal you staged yourself, use ${WITHDRAW_TOOL_NAME} through gnubok_stage_tool.`
    : `${lacks} Do not retry: ask the user to do this in the web app, or to connect again with a key that carries ${required}.`
}

/**
 * Inline SIE content above this length is refused: a model reproducing tens
 * of thousands of tokens verbatim WILL eventually truncate mid-#VER, and a
 * truncated file that still parses imports silently incomplete bookkeeping.
 * Larger files go through gnubok_create_sie_upload (raw bytes, no model in
 * the path). ~120k chars ≈ a few thousand verifikat rows.
 */
const MAX_INLINE_SIE_CHARS = 120_000

/** How many draft verifikat gnubok_year_end_readiness lists by id; draft_count is the total. */
const YEAR_END_READINESS_DRAFT_LIMIT = 20

/**
 * Resolve SIE file content from tool args, three sources in priority order:
 *
 *   - upload_id: raw bytes PUT to a gnubok_create_sie_upload URL. The only
 *     path with no model in the loop; required for large files.
 *   - file_content_base64: exact bytes base64-encoded (e.g. from a
 *     code-execution sandbox).
 *   - file_content: plain text as the model read the attachment.
 *
 * Byte paths run the same encoding detection as the HTTP upload route, so
 * CP437 exports keep their åäö. An optional sha256 (hex, of the RAW BYTES)
 * is verified on the two byte-exact paths and proves the content was not
 * truncated or altered in transit; it cannot be checked for plain text
 * (the model's read may legitimately differ from the file's bytes).
 * Returns null when no source is usable.
 */
async function resolveSieToolContent(
  args: Record<string, unknown>,
  companyId: string,
  userId: string
): Promise<string | null> {
  const sha256 = typeof args.sha256 === 'string' ? args.sha256.trim().toLowerCase() : null
  const verifyBytes = (buffer: Buffer, source: string) => {
    if (!sha256) return
    const actual = createHash('sha256').update(buffer).digest('hex')
    if (actual !== sha256) {
      throw codedError(
        'VALIDATION_ERROR',
        `sha256 mismatch on ${source}: expected ${sha256}, got ${actual}. The content was truncated or altered; re-send it.`
      )
    }
  }

  const { detectEncoding, decodeBuffer } = await import('@/lib/import/sie-parser')

  if (typeof args.upload_id === 'string' && args.upload_id.length > 0) {
    const fileName = typeof args.filename === 'string' ? args.filename : ''
    if (!fileName) {
      throw codedError('VALIDATION_ERROR', 'filename is required together with upload_id')
    }
    // The same check as gnubok_complete_document_upload: an upload_id is the
    // UUID gnubok_create_sie_upload returned, nothing else.
    if (!isUuid(args.upload_id)) {
      throw badArgument('upload_id', 'upload_id must be the upload_id gnubok_create_sie_upload returned.')
    }
    const service = createServiceClientNoCookies()
    const pendingPath = buildPendingDocumentStoragePath(companyId, userId, args.upload_id, fileName)
    const { data, error } = await service.storage.from(DOCUMENTS_BUCKET).download(pendingPath)
    if (error || !data) {
      throw codedError(
        'NOT_FOUND',
        // The pending key carries the company: an upload_id made for one
        // company is not found from another, so name that cause too.
        'No uploaded file found for this upload_id in this company. PUT the raw file bytes to the upload_url from gnubok_create_sie_upload first, with its upload_headers (same upload_id and filename), and pass the company_id that upload was created for.'
      )
    }
    const buffer = Buffer.from(await data.arrayBuffer())
    verifyBytes(buffer, 'the uploaded file')
    const arrayBuffer = buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength)
    return decodeBuffer(arrayBuffer, detectEncoding(arrayBuffer))
  }

  if (typeof args.file_content_base64 === 'string' && args.file_content_base64.length > 0) {
    // The inline cap exists to stop a MODEL from retyping a large file with
    // silent truncation. A caller that provides sha256 (the drop-card widget
    // always does) has byte-exact content and the hash check below IS the
    // truncation guard, so the cap does not apply.
    if (!sha256 && args.file_content_base64.length > MAX_INLINE_SIE_CHARS) {
      throw codedError(
        'VALIDATION_ERROR',
        'File too large to pass inline safely without a sha256. Use gnubok_create_sie_upload (drag-and-drop card / PUT to its upload_url with its upload_headers) and pass the upload_id here, or include sha256 of the raw bytes.'
      )
    }
    const buffer = Buffer.from(args.file_content_base64, 'base64')
    verifyBytes(buffer, 'file_content_base64')
    const arrayBuffer = buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength)
    return decodeBuffer(arrayBuffer, detectEncoding(arrayBuffer))
  }

  if (typeof args.file_content === 'string' && args.file_content.length > 0) {
    if (args.file_content.length > MAX_INLINE_SIE_CHARS) {
      throw codedError(
        'VALIDATION_ERROR',
        'File too large to pass inline safely (silent mid-verifikat truncation risk). Use gnubok_create_sie_upload, PUT the raw bytes to its upload_url with its upload_headers, and pass the upload_id here instead.'
      )
    }
    return args.file_content
  }
  return null
}

/** The company a SIE file is imported into, as the drop card and the agent are shown it. */
interface SieTargetCompany {
  company_id: string
  name: string | null
  org_number: string | null
}

/**
 * Which company the SIE tools are about to import into: its display name
 * (company_settings.company_name, else companies.name, the order the company
 * echo uses) and its org number by the same read the org-number check uses
 * (readCompanyOrgNumber), so the number the card shows is the number the
 * file was compared with.
 */
async function readSieTargetCompany(supabase: SupabaseClient, companyId: string): Promise<SieTargetCompany> {
  const { readCompanyOrgNumber } = await import('@/lib/company/org-number')
  const [orgNumber, company, settings] = await Promise.all([
    readCompanyOrgNumber(supabase, companyId),
    supabase.from('companies').select('name').eq('id', companyId).maybeSingle(),
    supabase.from('company_settings').select('company_name').eq('company_id', companyId).maybeSingle(),
  ])
  const companyName = (company.data as { name?: string | null } | null)?.name?.trim()
  const settingsName = (settings.data as { company_name?: string | null } | null)?.company_name?.trim()
  return { company_id: companyId, name: settingsName || companyName || null, org_number: orgNumber }
}

/**
 * Other companies this connection reaches whose org number is the SIE file's
 * #ORGNR: where a file that does not belong to the current company most
 * likely belongs. A file whose #ORGNR differs from the company's most often
 * carries the number of another company the same user is a member of. Same
 * reach as a
 * wrong company_id's candidates (listAccessibleCompanies: key allowlist or
 * pin, no archived or seat-paused company) and the same number key as the
 * check itself (orgNumberKey). Best effort: a failed lookup names nothing.
 */
async function findCompaniesWithSieOrgNumber(
  supabase: SupabaseClient,
  userId: string,
  actor: ActorContext | undefined,
  fileOrgNumber: string | null,
  currentCompanyId: string,
): Promise<Array<{ company_id: string; name: string }>> {
  const [{ orgNumberKey, sameOrgNumber }, { effectiveOrgNumber }] = await Promise.all([
    import('@/lib/invariants/org-number'),
    import('@/lib/company/org-number'),
  ])
  if (!orgNumberKey(fileOrgNumber)) return []
  try {
    const reachable = (await listAccessibleCompanies(supabase, userId, effectiveCompanyRestriction(actor)))
      .filter((company) => company.company_id !== currentCompanyId)
    if (reachable.length === 0) return []
    const ids = reachable.map((company) => company.company_id)
    const [companies, settings] = await Promise.all([
      supabase.from('companies').select('id, org_number').in('id', ids),
      supabase.from('company_settings').select('company_id, org_number').in('company_id', ids),
    ])
    const settingsByCompany = new Map(
      ((Array.isArray(settings.data) ? settings.data : []) as Array<{ company_id: string; org_number: string | null }>)
        .map((row) => [row.company_id, row.org_number]),
    )
    const companyById = new Map(
      ((Array.isArray(companies.data) ? companies.data : []) as Array<{ id: string; org_number: string | null }>)
        .map((row) => [row.id, row.org_number]),
    )
    return reachable
      .filter((company) => sameOrgNumber(fileOrgNumber, effectiveOrgNumber(settingsByCompany.get(company.company_id), companyById.get(company.company_id))))
      .slice(0, 3)
  } catch {
    return []
  }
}

/**
 * One-session banks this user already reads through Enable Banking in OTHER
 * companies, with those companies (crm#1201). At such a bank (SEB, see
 * ONE_SESSION_BANKS) a person's login holds one active Enable Banking
 * consent, so connecting it for a second company stops the first company's
 * feed; the web page warns before BankID, and gnubok_connect_bank has to say
 * it before it hands out the link. Only companies this connection reaches are
 * named (listAccessibleCompanies). Best effort: a failed read names nothing.
 */
async function oneSessionBankElsewhere(
  supabase: SupabaseClient,
  userId: string,
  actor: ActorContext | undefined,
  companyId: string,
): Promise<Array<{ bank: string; companies: Array<{ company_id: string; name: string }> }>> {
  try {
    const { data, error } = await supabase
      .from('bank_connections')
      .select('company_id, bank_name')
      .eq('user_id', userId)
      .eq('aggregator', ENABLE_BANKING_AGGREGATOR)
      .eq('status', 'active')
      .neq('company_id', companyId)
    if (error || !Array.isArray(data)) return []
    const rows = (data as Array<{ company_id: string; bank_name: string | null }>).filter(
      (row) => row.bank_name && isOneSessionBank(row.bank_name),
    )
    if (rows.length === 0) return []
    const names = new Map(
      (await listAccessibleCompanies(supabase, userId, effectiveCompanyRestriction(actor))).map(
        (company) => [company.company_id, company.name] as const,
      ),
    )
    const byBank = new Map<string, Map<string, string>>()
    for (const row of rows) {
      const name = names.get(row.company_id)
      if (!name) continue
      const bank = row.bank_name!.trim()
      const companies = byBank.get(bank) ?? new Map<string, string>()
      companies.set(row.company_id, name)
      byBank.set(bank, companies)
    }
    return [...byBank].map(([bank, companies]) => ({
      bank,
      companies: [...companies].map(([id, name]) => ({ company_id: id, name })),
    }))
  } catch {
    return []
  }
}

/**
 * Absolute origin for links the user opens in a browser. A deployment
 * without NEXT_PUBLIC_APP_URL falls back to localhost in getCanonicalBaseUrl,
 * which would hand a remote user an unusable link: refuse instead.
 */
function connectLinkBaseUrl(): string {
  if (!process.env.NEXT_PUBLIC_APP_URL) {
    throw codedError(
      'INTERNAL_ERROR',
      'NEXT_PUBLIC_APP_URL is not configured on this installation; cannot build a connect link'
    )
  }
  return getCanonicalBaseUrl()
}

/**
 * How the connection that just created a company reaches it:
 *   - 'default': the user had no other company, so the key binds to the new
 *     one on its next call (bindUnboundKey) and company_id can be omitted;
 *   - 'explicit': the user has another company, which stays the default, so
 *     every call for the new one must name it;
 *   - 'unreachable': the connection is pinned or limited to a list of
 *     companies that does not include the new one.
 * A failed membership read answers 'explicit': naming the company is right
 * in every case, omitting it is right in one.
 */
async function newCompanyReach(
  supabase: SupabaseClient,
  userId: string,
  actor: ActorContext | undefined,
  newCompanyId: string,
): Promise<'default' | 'explicit' | 'unreachable'> {
  const restriction = effectiveCompanyRestriction(actor)
  if (restriction && !restriction.some((id) => id.toLowerCase() === newCompanyId.toLowerCase())) return 'unreachable'
  try {
    const { data, error } = await supabase
      .from('company_members')
      .select('company_id, companies!inner(archived_at)')
      .eq('user_id', userId)
      .neq('company_id', newCompanyId)
      .is('companies.archived_at', null)
      .limit(1)
    if (error || !Array.isArray(data)) return 'explicit'
    return data.length === 0 ? 'default' : 'explicit'
  } catch {
    return 'explicit'
  }
}

/**
 * The team a company created through the API/MCP path attaches to when the
 * caller does not name one: the user's PERSONAL team only (WL-08: companies
 * created through the normal flow always attach to the personal team; cockpit
 * flows pass the byrå team id explicitly). Picking the first membership
 * regardless of kind attached a consultant's private company to their byrå
 * team, exposing their books to the whole byrå and suppressing the trial.
 * Mirrors ensure_user_team: earliest teams row with kind='personal'. null
 * when the user has no personal team; create_company_for_user then leaves
 * team_id NULL. Explicit team_id args are authorized by the DB gate instead.
 */
async function defaultTeamForUser(supabase: SupabaseClient, userId: string): Promise<string | null> {
  const { data, error } = await supabase
    .from('team_members')
    .select('team_id, teams!inner(kind, created_at)')
    .eq('user_id', userId)
    .eq('teams.kind', 'personal')
    .order('teams(created_at)', { ascending: true })
    .order('teams(id)', { ascending: true })
    .limit(1)
    .maybeSingle()
  if (error) {
    log.warn('default team lookup failed', { error: error.message })
    return null
  }
  return (data?.team_id as string | undefined) ?? null
}

function paginatedSchema(
  itemsKey: string,
  itemSchema: Record<string, unknown> = { type: 'object' },
  extraProperties: Record<string, unknown> = {},
) {
  return {
    type: 'object',
    properties: {
      [itemsKey]: { type: 'array', items: itemSchema },
      ...PAGINATION_PROPS,
      ...extraProperties,
    },
    required: [itemsKey, 'count', 'total_count', 'has_more'],
  } as const
}

