/**
 * gnubok_year_end_readiness: YearEndBlockerCode to the blocker `kind` this
 * tool publishes. The kinds are the public contract agents switch on, so they
 * are deliberately NOT the codes themselves: a code may be renamed or split
 * without breaking a consumer, as long as it keeps mapping to the same kind.
 *
 * UNBOOKED_CHECK_FAILED shares 'unbooked_transactions' with the real count:
 * the fail-closed variant means "we could not tell", and an agent should react
 * to it the same way (go look at the transactions, then re-run readiness).
 *
 * Exported so the tool-description test can assert that every kind an agent
 * can receive is actually named in the description it plans against: the
 * description drifted once already (it advertised FX revaluation, a WARNING,
 * as a blocker and never mentioned unbooked transactions, the common one).
 */
export const YEAR_END_BLOCKER_KIND: Record<YearEndBlockerCode, string> = {
  PERIOD_NOT_FOUND: 'period_not_found',
  PERIOD_NOT_ENDED: 'period_not_ended',
  PERIOD_ALREADY_CLOSED: 'period_already_closed',
  PERIOD_LOCKED: 'period_locked',
  CLOSING_ENTRY_EXISTS: 'closing_entry_exists',
  DRAFT_ENTRIES: 'draft_entries',
  // The fail-closed variant of the draft count, like UNBOOKED_CHECK_FAILED:
  // "we could not tell", so the agent reacts as to drafts (look, re-run).
  DRAFT_CHECK_FAILED: 'draft_entries',
  UNEXPLAINED_VOUCHER_GAP: 'unexplained_voucher_gap',
  SEQUENCE_COUNTER_BEHIND: 'sequence_mismatch',
  TRIAL_BALANCE_UNBALANCED: 'trial_balance_unbalanced',
  CONTINUITY_MISMATCH: 'opening_balance_continuity',
  NEXT_PERIOD_HAS_IB: 'next_period_ib_posted',
  NEXT_PERIOD_NOT_CALENDAR_YEAR: 'next_period_not_calendar_year',
  NEXT_PERIOD_OVERLAPS: 'next_period_overlaps',
  KONTANTMETOD_CUTOFF_REQUIRED: 'kontantmetod_cutoff_required',
  KONTANTMETOD_CUTOFF_CHECK_FAILED: 'kontantmetod_cutoff_required',
  UNBOOKED_TRANSACTIONS: 'unbooked_transactions',
  UNBOOKED_CHECK_FAILED: 'unbooked_transactions',
  PRIOR_RESULT_NOT_DISPOSED: 'prior_result_left',
  // Same kind, the other direction: more than the prior result was moved off.
  // The message says which way to correct.
  PRIOR_RESULT_OVER_DISPOSED: 'prior_result_left',
  // A period-state kind like period_locked: the message names the import and
  // the two buttons (Fortsätt, Ångra import) that release the year.
  SIE_IMPORT_UNFINISHED: 'sie_import_unfinished',
  // The fail-closed variant of the gap check, like UNBOOKED_CHECK_FAILED: "we
  // could not tell", so the agent reacts as to a gap (list the gaps, re-run).
  VOUCHER_GAP_CHECK_FAILED: 'unexplained_voucher_gap',
  // A period-state kind like period_locked, for the other lock: the company
  // lock date covers the year's last day. The message names the date and the
  // way out, and the blocker carries the remediation with the tool.
  COMPANY_LOCK_DATE: 'company_lock_date',
  COMPANY_LOCK_DATE_CHECK_FAILED: 'company_lock_date',
}

/**
 * Wording fallback for a blocker whose code is not in YEAR_END_BLOCKER_KIND.
 * Kept so an unmapped or legacy English message still routes somewhere useful
 * instead of collapsing to 'other'.
 */
function classifyYearEndBlockerMessage(message: string): string {
  if (/draft journal entries|utkast måste bokföras/i.test(message)) return 'draft_entries'
  if (/unbooked transaction|saknar bokföring|obokförda transaktioner/i.test(message)) return 'unbooked_transactions'
  if (/voucher gap|verifikationsnummerglapp/i.test(message)) return 'unexplained_voucher_gap'
  if (/Sequence counter integrity|Nummerserien i serie/i.test(message)) return 'sequence_mismatch'
  if (/Trial balance is not balanced|Råbalansen balanserar inte/i.test(message)) return 'trial_balance_unbalanced'
  if (/already closed|redan stängd/i.test(message)) return 'period_already_closed'
  if (/has not yet ended|slutdatumet har inte passerat/i.test(message)) return 'period_not_ended'
  if (/closing entry already exists|Bokslutsverifikation finns redan/i.test(message)) return 'closing_entry_exists'
  if (/continuity check failed|IB\/UB-kontinuiteten/i.test(message)) return 'opening_balance_continuity'
  if (/opening balances already posted|redan ingående balanser bokförda/i.test(message)) return 'next_period_ib_posted'
  if (/Fiscal period not found|Räkenskapsperioden hittades inte/i.test(message)) return 'period_not_found'
  return 'other'
}

// ── agent_memory dedup helpers ───────────────────────────────
// Cheap, embedding-free near-duplicate detection for gnubok_remember_fact.
// Lowercase, strip punctuation, drop very short / stop-ish words, and
// compare two memories by Jaccard similarity over their word sets. Good
// enough to catch the agent re-remembering the same fact in slightly
// different words; not a substitute for semantic embeddings, but zero-cost.
const MEMORY_DEDUP_STOPWORDS = new Set([
  'och', 'att', 'det', 'som', 'en', 'ett', 'är', 'för', 'med', 'på', 'av',
  'till', 'den', 'de', 'i', 'om', 'har', 'var', 'kan', 'ska', 'samt',
  'the', 'a', 'an', 'is', 'are', 'for', 'with', 'of', 'to', 'and', 'in',
])

function tokenizeForDedup(text: string): Set<string> {
  const tokens = text
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .split(/\s+/)
    .filter((t) => t.length >= 3 && !MEMORY_DEDUP_STOPWORDS.has(t))
  return new Set(tokens)
}

function jaccardSimilarity(a: Set<string>, b: Set<string>): number {
  if (a.size === 0 || b.size === 0) return 0
  let intersection = 0
  for (const t of a) if (b.has(t)) intersection++
  const union = a.size + b.size - intersection
  return union === 0 ? 0 : intersection / union
}

/** How a fact reached gnubok_remember_fact (agent_memory.origin, migration 20261029122000). */
const REMEMBER_ORIGINS = ['conversation', 'session_sync', 'onboarding_import'] as const

/**
 * Where a note about one purchase belongs: on its verifikat, not in memory.
 * One sentence, said in gnubok_remember_fact's description and in the
 * briefing's memory line.
 */
const PURCHASE_NOTE_PLACE =
  "A note about one purchase or verifikat (who took part, what a receipt was for) goes on that verifikat with gnubok_set_voucher_note or in the booking's description, not here."

/**
 * The briefing's directions to everything an agent may need about the
 * company, so it reads the right place instead of guessing. Plain lines:
 * undeclared in outputSchema like the other briefing guidance (tools/list budget).
 */
const WHERE_TO_FIND = [
  `memory: every fact agents were told about this company, newest first; a later fact settles an earlier one. Save a new one with gnubok_remember_fact; pass replaces with the old fact_id when it updates one. ${PURCHASE_NOTE_PLACE}`,
  'ledger_context (all of it: Accounted://ledger/context): how this company has booked each counterparty and supplier.',
  'Documents: gnubok_search_records and gnubok_read_document (arkiv explains, when present).',
  'Workflows: gnubok_list_skills, then gnubok_load_skill; a curated workflow arrives with the company facts inline.',
]

/** The briefing's invitation to offer what the AI already knows (origin session_sync). */
const MEMORY_SYNC_NOTE =
  'If you know facts about this business from your own memory or earlier chats that are not in memory, offer once in this conversation to save them with gnubok_remember_fact (origin: session_sync). Skip it when you have nothing new or the user said no before.'

/**
 * The company's fiscal period that contains an ISO date, or null. A date in a
 * report call names the year the caller wants: "resultatrapporten för 2023"
 * arrives as from_date/to_date, not as a period_id the model would first
 * have to look up (#2185).
 */
async function findFiscalPeriodContaining(
  supabase: SupabaseClient,
  companyId: string,
  date: string,
): Promise<{ id: string; name: string; period_start: string; period_end: string } | null> {
  const { data } = await supabase
    .from('fiscal_periods')
    .select('id, name, period_start, period_end')
    .eq('company_id', companyId)
    .lte('period_start', date)
    .gte('period_end', date)
    .order('period_start', { ascending: false })
    .limit(1)
    .maybeSingle()
  return data ?? null
}

/** "the company's fiscal periods span A to B", for an error that names a date no period covers. */
async function describeFiscalPeriodSpan(supabase: SupabaseClient, companyId: string): Promise<string> {
  const { data } = await supabase
    .from('fiscal_periods')
    .select('period_start, period_end')
    .eq('company_id', companyId)
    .order('period_start', { ascending: true })
  const rows = (data ?? []) as { period_start: string; period_end: string }[]
  if (rows.length === 0) return 'the company has no fiscal periods'
  return `the company's fiscal periods span ${rows[0].period_start} to ${rows[rows.length - 1].period_end}`
}

/**
 * Resolve the fiscal period a report tool runs against: the caller's
 * `period_id` when given; else, when the call carries a date (from_date,
 * as_of_date, ...), the period that contains that date; else the company's
 * most recent period. An explicit id is re-read scoped to the company, so a
 * foreign id never resolves.
 *
 * The date fallback exists because the previous default (most recent period,
 * then a loud range check) made every question about an earlier year fail
 * unless the model had first looked up that year's UUID (#2185).
 *
 * Each refusal is PERIOD_NOT_FOUND: as plain errors they answered
 * UNKNOWN_ERROR, "try again", for a period no retry will find.
 */
async function resolveReportPeriod(
  supabase: SupabaseClient,
  companyId: string,
  periodIdArg: unknown,
  noPeriodsMessage: string,
  dateHint?: unknown,
) {
  let periodId = periodIdArg as string | undefined

  if (!periodId && typeof dateHint === 'string' && ISO_DATE_RE.test(dateHint)) {
    const containing = await findFiscalPeriodContaining(supabase, companyId, dateHint)
    if (containing) return containing
    const span = await describeFiscalPeriodSpan(supabase, companyId)
    throw codedRefusal(
      'PERIOD_NOT_FOUND',
      `No fiscal period contains ${dateHint}: ${span}. ` +
      `Pass a date inside one of them, or that period's period_id (gnubok_list_fiscal_periods).`,
    )
  }

  if (!periodId) {
    const { data: periods } = await supabase
      .from('fiscal_periods')
      .select('id')
      .eq('company_id', companyId)
      .order('period_start', { ascending: false })
      .limit(1)
      .single()

    if (!periods) throw codedRefusal('PERIOD_NOT_FOUND', noPeriodsMessage)
    periodId = periods.id
  }

  const { data: period } = await supabase
    .from('fiscal_periods')
    .select('id, name, period_start, period_end')
    .eq('id', periodId)
    .eq('company_id', companyId)
    .single()

  if (!period) {
    throw codedRefusal('PERIOD_NOT_FOUND', 'Fiscal period not found in this company: gnubok_list_fiscal_periods lists its period_ids.')
  }
  return period
}

/**
 * The fiscal period gnubok_list_voucher_gaps checks: the caller's
 * fiscal_period_id, re-read in the company; omitted, the period containing
 * today, else the most recent one. The id used to reach SQL as given, so an
 * omitted one arrived as the string "undefined" (supabase-js stringifies
 * it) and a placeholder as itself, each answering UNKNOWN_ERROR "try again"
 * for a call no retry fixes, and another company's id answered 0 gaps for a
 * year that was never checked.
 */
async function resolveVoucherGapPeriod(supabase: SupabaseClient, companyId: string, periodIdArg: unknown) {
  if (periodIdArg === undefined || periodIdArg === null || periodIdArg === '') {
    const current = await findFiscalPeriodContaining(supabase, companyId, todayIsoStockholm())
    if (current) return current
    return resolveReportPeriod(supabase, companyId, undefined, 'The company has no fiscal periods yet, so there are no voucher series to check.')
  }
  if (!isUuid(periodIdArg)) {
    throw badArgument(
      'fiscal_period_id',
      'fiscal_period_id must be a period_id from gnubok_list_fiscal_periods, or omitted for the current year.',
      'Ange ett räkenskapsårs id, eller utelämna fältet för innevarande räkenskapsår.',
    )
  }
  return resolveReportPeriod(supabase, companyId, periodIdArg, '')
}

/** Invoice row plus its customer, scoped to the company; throws when absent. */
async function fetchInvoiceWithCustomer(supabase: SupabaseClient, companyId: string, invoiceId: string) {
  const { data: invoice, error: invoiceError } = await supabase
    .from('invoices')
    .select('*, customer:customers(*)')
    .eq('id', invoiceId)
    .eq('company_id', companyId)
    .single()

  if (invoiceError || !invoice) throw codedRefusal('NOT_FOUND', 'Invoice not found')
  return invoice
}

/** Offset-pagination tail shared by the list tools: count/total/has_more/next_offset. */
function pageTail(rows: unknown[], total: number, offset: number) {
  const hasMore = offset + rows.length < total
  return {
    count: rows.length,
    total_count: total,
    has_more: hasMore,
    ...(hasMore ? { next_offset: offset + rows.length } : {}),
  }
}

/**
 * Bytes a tools/call result costs on the wire. handleMcpRequest answers with
 * one buffered JSON body that carries the result twice: pretty-printed in
 * content[0].text, a JSON string, so its quotes and newlines are escaped
 * again, and compact as structuredContent.
 */
export function toolResultWireBytes(result: unknown): number {
  const text = JSON.stringify(result, null, 2)
  return Buffer.byteLength(JSON.stringify({ content: [{ type: 'text', text }], structuredContent: result }), 'utf8')
}

/**
 * What one tools/call answer may weigh on the hosted service. The route
 * answers with a buffered body (NextResponse.json), and Vercel refuses a
 * buffered function response over 4.5 MB (4 500 000 bytes, the stricter
 * reading); the 20 000 left over are room for the JSON-RPC envelope, _meta
 * and the company block the text carries for a key that reaches several
 * companies, together well under 2 000 bytes.
 */
export const MCP_ANSWER_BUDGET_BYTES = 4_480_000

/**
 * Whether a result fits one answer. Self-hosted Docker has no such limit, so
 * there everything fits, as it always did. Each of the two copies is at
 * least the compact JSON, so a register far over the budget is not printed
 * twice to find that out.
 */
function fitsOneAnswer(result: unknown): boolean {
  if (isSelfHosted()) return true
  if (2 * Buffer.byteLength(JSON.stringify(result), 'utf8') > MCP_ANSWER_BUDGET_BYTES) return false
  return toolResultWireBytes(result) <= MCP_ANSWER_BUDGET_BYTES
}

// A page of 100 customers is about 42 000 characters of text, under the
// 25 000 tokens at which some MCP hosts cut a tool result.
const REGISTER_PAGE_SIZE = 100

/**
 * The answer of a register list (customers, articles), cut from the whole
 * register in its display order (crm#2151). With limit or offset: that page,
 * at most 100 rows. Without either: the whole register, as these tools have
 * always answered, when it fits one answer; a register too large for one
 * answer, which could not be answered at all before, gets its first page,
 * with has_more, next_offset and total_count saying there is more. `present`
 * shapes the rows answered and runs on them alone (the customer list opens
 * personnummer there). Whether the whole register fits is measured on
 * `measure`, which must answer rows at least as large as `present`'s without
 * opening anything.
 */
function registerAnswer<Row, Out>(
  key: string,
  sorted: Row[],
  args: Record<string, unknown>,
  present: (rows: Row[]) => Out[],
  measure: (rows: Row[]) => unknown[] = present,
): Record<string, unknown> {
  if (args.limit == null && args.offset == null) {
    if (fitsOneAnswer({ [key]: measure(sorted), ...pageTail(sorted, sorted.length, 0) })) {
      const rows = present(sorted)
      return { [key]: rows, ...pageTail(rows, rows.length, 0) }
    }
  }
  const limit = Math.min(Math.max(1, Math.floor(Number(args.limit)) || REGISTER_PAGE_SIZE), REGISTER_PAGE_SIZE)
  const offset = Math.max(0, Math.floor(Number(args.offset)) || 0)
  const rows = present(sorted.slice(offset, offset + limit))
  return { [key]: rows, ...pageTail(rows, sorted.length, offset) }
}

// Shared by the report tools' optional `dimensions` filter arg: parse the raw
// bag, then resolve value NAMES → registry codes in one pass (resolve-don't-
// select: the exact contract gnubok_create_voucher uses, incl. free-text
// passthrough while dimensions_enabled is off). A DimensionResolutionError
// propagates to the caller with ranked candidates. The resolved bag is echoed
// back as `dimension_filter` so the agent can verify what a name attached to.
async function resolveReportDimensionFilter(
  supabase: SupabaseClient,
  companyId: string,
  raw: unknown,
): Promise<{ filter?: Record<string, string>; resolutions: DimensionResolution[] }> {
  if (!raw || typeof raw !== 'object' || Object.keys(raw as object).length === 0) {
    return { resolutions: [] }
  }
  const parsed = parseDimensionsArg(raw, 'dimensions')
  const { bags, resolutions } = await resolveDimensionBags(supabase, companyId, [parsed])
  return { filter: bags[0], resolutions }
}

// Input-schema fragment for that arg: identical shape on trial balance,
// income statement, and general ledger.
const REPORT_DIMENSIONS_FILTER_SCHEMA = {
  type: 'object',
  additionalProperties: { type: 'string' },
  description: 'Filter: SIE dim no → value (code OR name), e.g. {"6":"P001"}. IB is scoped to it too: its tagged IB lines or prior tagged history (a project carries its balance; 26xx and annually reset dimensions open at 0).',
} as const

// Optional custom date range on the report tools. Historically from_date /
// to_date were silently dropped (the inputSchema said additionalProperties:
// false but nothing enforced it), so an agent asking for January-July got the
// full fiscal year back with no signal. Validate loudly instead.
function parseReportRangeArgs(
  args: Record<string, unknown>,
  period: { period_start: string; period_end: string },
  keys: { from?: string; to: string },
): { fromDate?: string; toDate?: string } {
  const rawFrom = keys.from ? (args[keys.from] as string | undefined) : undefined
  const rawTo = args[keys.to] as string | undefined

  for (const [key, value] of [[keys.from, rawFrom], [keys.to, rawTo]] as const) {
    if (value === undefined || key === undefined) continue
    if (typeof value !== 'string' || !ISO_DATE_RE.test(value)) {
      throw badArgument(key, `${key} must be an ISO date (YYYY-MM-DD).`)
    }
    if (value < period.period_start || value > period.period_end) {
      throw badArgument(
        key,
        `${key} must be within the fiscal period (${period.period_start} to ${period.period_end}). ` +
        `For another year, pass that year's period_id.`,
      )
    }
  }
  if (rawFrom && rawTo && rawFrom > rawTo) {
    throw badArgument(keys.from ?? 'from', `${keys.from} must not be after ${keys.to}.`)
  }
  return { fromDate: rawFrom, toDate: rawTo }
}

// Reject unknown args on tools that opt in, instead of silently ignoring
// them: a misspelled parameter (fromdate=) must not degrade to a full-period
// report the agent mistakes for the range it asked for.
function rejectUnknownArgs(args: Record<string, unknown>, allowed: readonly string[]): void {
  const unknown = Object.keys(args).filter((k) => !allowed.includes(k))
  if (unknown.length > 0) {
    throw badArgument(
      unknown[0],
      `Unknown parameter(s): ${unknown.join(', ')}. Allowed: ${allowed.join(', ')}. ` +
      `Unknown parameters are rejected rather than silently ignored.`,
    )
  }
}

// Output-schema fragments for the echo fields (never in `required`).
const DIMENSION_FILTER_OUTPUT_PROPS = {
  dimension_filter: {
    type: 'object',
    additionalProperties: { type: 'string' },
    description: 'Echo of the applied filter, resolved to registry codes.',
  },
  dimension_resolutions: {
    type: 'array',
    items: { type: 'object' },
    description: 'Non-exact name→code resolution echoes (resolve-don\'t-select).',
  },
} as const

let canonicalToolNamesCache: ReadonlySet<string> | undefined

function getCanonicalToolNames(): ReadonlySet<string> {
  canonicalToolNamesCache ??= new Set(tools.map((tool) => tool.name))
  return canonicalToolNamesCache
}

function projectMcpPayload<T>(value: T, namespace: McpToolNamespace): T {
  return projectToolReferences(value, namespace, getCanonicalToolNames())
}

