/**
 * Every staging tool takes the agent's reason (lib/pending-operations/
 * agent-reason.ts): the optional `reason` property is added here, once,
 * rather than tool by tool. A tool whose own input already has `reason`
 * keeps its own (agentReason 'own'). execute() is left as written: its
 * source is what staging-behaviour.test.ts reads. Replaced in place, before
 * anything below reads the list.
 */
export function withAgentReasonArg(t: McpTool): McpTool {
  if (!isStagingTool(t)) return t
  const properties = (t.inputSchema.properties ?? {}) as Record<string, unknown>
  if (AGENT_REASON_ARG in properties) return { ...t, agentReason: 'own' }
  return {
    ...t,
    agentReason: 'added',
    inputSchema: { ...t.inputSchema, properties: { ...properties, [AGENT_REASON_ARG]: AGENT_REASON_PROPERTY } },
  }
}

tools.forEach((t, i) => {
  tools[i] = withAgentReasonArg(t)
})

// Drift guard for the gnubok_get_agent_briefing recommended_tools loadouts:
// every referenced tool must exist in the registry above and every referenced
// skill must be a real workflow skill. Runs at module init so a rename or
// removal fails the build (and every test importing this module) instead of
// shipping a briefing that recommends phantom tools.
assertRecommendedLoadoutsValid(new Set(tools.map((t) => t.name)))

/**
 * Exactly the writes gnubok_stage_tool (and, as a fallback, gnubok_call_tool)
 * will carry: writes that declare the staged envelope and are absent from
 * tools/list. Derived from the registry,
 * never hand-listed, so it cannot drift from bridgeRefusalReason (a test pins
 * that the two agree tool by tool). The bridges themselves are not in it: their
 * pass-through outputSchema is not the staged envelope.
 */
export const STAGE_BRIDGE_TARGETS: readonly McpTool[] = tools.filter(
  (t) => isStagingTool(t) && !isDefaultCatalogTool(t) && t.annotations.effect !== 'read_only',
)

/**
 * Whether tools/list shows gnubok_stage_tool to this key. It has no scope of
 * its own (the target's scope is what the dispatcher enforces), so without
 * this a read-only key would be shown a tool whose every call is
 * scope-denied: listed but unusable, the smell issue #2800 is about.
 */
function keyCanStageThroughBridge(keyScopes: ApiKeyScope[]): boolean {
  return STAGE_BRIDGE_TARGETS.some((t) => {
    const required = TOOL_SCOPE_MAP[t.name]
    return !required || hasScope(keyScopes, required)
  })
}

/**
 * Who is asking, as far as tools/list is concerned. The dispatcher builds it
 * from the request (token, reachable companies, key scopes) for tools/list
 * and injects the same three facts into gnubok_search_tools and
 * gnubok_get_agent_briefing.
 */
export interface CatalogViewer {
  anonymous: boolean
  simpleCompanyMode: boolean
  keyScopes: ApiKeyScope[]
  /**
   * Modules the company does not have, by the resolved capabilities
   * (capabilitySurface in lib/modules/capabilities.ts): their package is
   * switched off or not in the company's country. Their tools are not
   * listed, as their pages are not in the menu. Only for a single-company
   * connection; empty for every company today.
   */
  hiddenModules?: ReadonlySet<ModuleId>
  /**
   * The connection was minted for a host that renders Accounted's approval
   * view (view-approval.ts): only then is the view's own door listed, app-only.
   */
  approvalView?: boolean
}

/**
 * The one definition of what tools/list shows a caller. The tools/list
 * handler filters with it, and every callable_via (search hits, the
 * briefing's recommended_tools, unknown-tool suggestions) is derived from it
 * through callableViaFor, so discovery cannot say "tools_list" for a tool the
 * caller's list omits. Those used to be two copies: tools/list filtered
 * inline while callable_via read only the registry tier, so a single-company
 * key's briefing called gnubok_list_companies listed and a key that could
 * stage nothing was told gnubok_stage_tool was (agent feedback seq 995216).
 */
export function isListedFor(t: McpTool, viewer: CatalogViewer): boolean {
  // A view-only tool (the approval view's door) is listed, app-only, only to
  // a connection that has the view; the host keeps it from the model. Every
  // other gate below applies to it as to any tool.
  if (isViewOnlyTool(t) ? viewer.approvalView !== true : !isDefaultCatalogTool(t)) return false
  // One company (or none): the company switch and the cross-company tools
  // have nothing to work on.
  if (viewer.simpleCompanyMode && isMultiCompanyOnlyTool(t.name)) return false
  // The resolved capabilities: a tool of a module whose package the company
  // does not have is left out, as the menu leaves out its pages.
  if (viewer.hiddenModules && viewer.hiddenModules.size > 0) {
    const owner = moduleForTool(t.name)
    if (owner && viewer.hiddenModules.has(owner)) return false
  }
  // Not connected yet: the whole default catalog is listed so the agent can
  // pick the right tool; calling a protected one is what produces the 401
  // challenge that starts the connect (and signup) flow.
  if (viewer.anonymous) return true
  // Unscoped itself, so gate it on whether this key could stage anything
  // through it (see keyCanStageThroughBridge).
  if (t.name === 'gnubok_stage_tool') return keyCanStageThroughBridge(viewer.keyScopes)
  const required = TOOL_SCOPE_MAP[t.name]
  return !required || hasScope(viewer.keyScopes, required)
}

/**
 * The tool a name the model gave resolves to: any tool but a view-only one
 * (view-approval.ts), which only an MCP Apps view calls by a direct
 * tools/call. Bridges and the cross-company runners resolve through this, so
 * none of them can carry the view's door or advise calling it.
 */
function findModelTool(name: string): McpTool | undefined {
  return tools.find((t) => t.name === name && !isViewOnlyTool(t))
}

const BRIDGE_TOOL_BY_VIA: Readonly<Record<'call_tool' | 'stage_tool', McpTool>> = {
  call_tool: tools.find((t) => t.name === 'gnubok_call_tool')!,
  stage_tool: tools.find((t) => t.name === 'gnubok_stage_tool')!,
}

/**
 * How THIS caller reaches a tool, read off its own tools/list (isListedFor).
 * A bridge counts only when the caller's list carries the bridge itself.
 */
export function callableViaFor(t: McpTool, viewer: CatalogViewer): ToolCallableVia {
  const via = toolCallableVia(t, { listed: isListedFor(t, viewer), stages: ridesStageBridge(t) })
  if (via === 'call_tool' || via === 'stage_tool') {
    return isListedFor(BRIDGE_TOOL_BY_VIA[via], viewer) ? via : 'none'
  }
  return via
}

// ── MCP Protocol Handler ─────────────────────────────────────

// Build identifier so MCP clients can tell deploys apart in `initialize`
// serverInfo. Resolved once at module load (constant per process, so the
// definitions layer stays deterministic); the same identifier /api/health
// and the behandlingshistorik report stamp. '1.0.0' is the self-hosted
// fallback when no commit SHA is inlined at build.
const SERVER_VERSION = currentAppVersion() ?? '1.0.0'

const SERVER_INFO_BY_NAMESPACE = {
  gnubok: {
    // Stable legacy identity for every existing connection.
    name: 'gnubok',
    title: 'Accounted',
    version: SERVER_VERSION,
  },
  accounted: {
    name: 'accounted',
    title: 'Accounted',
    version: SERVER_VERSION,
  },
} as const

const PROTOCOL_VERSION = '2025-06-18'

// ── Spec revision 2026-07-28 (stateless core) ────────────────
// New-style clients skip the initialize handshake and instead carry their
// protocol version and capabilities in _meta on every request. The handshake
// path keeps serving 2025-06-18-and-earlier clients unchanged: their
// responses stay byte-identical.
const STATELESS_PROTOCOL_VERSION = '2026-07-28'
const SUPPORTED_PROTOCOL_VERSIONS = [
  STATELESS_PROTOCOL_VERSION,
  '2025-06-18',
  '2025-03-26',
  '2024-11-05',
]
const META_PROTOCOL_VERSION = 'io.modelcontextprotocol/protocolVersion'
const META_SERVER_INFO = 'io.modelcontextprotocol/serverInfo'
// W3C trace context in _meta: the trace the message runs in (handleMcpRequest).
const META_TRACEPARENT = 'traceparent'
// 2026-07-28 reserves -32020..-32099 for spec-defined errors.
const JSONRPC_HEADER_MISMATCH = -32020
const JSONRPC_UNSUPPORTED_PROTOCOL_VERSION = -32022
// CacheableResult freshness hints. The tool/prompt catalog and widget HTML
// change only on deploy; skills live in the DB and can change between
// deploys; data resources are live ledger state and must never be cached.
// Everything is served behind Authorization, so cacheScope stays private.
// "Static" content (tools/list, widget HTML, prompts) is static only within
// one deploy: every deploy can add tools and change widgets. The 1-hour hint
// this used to carry made Claude.ai serve a pre-deploy catalog for up to an
// hour after a release: a freshly shipped tool flapped in and out of the
// connector's tool list depending on which fetch hit the client cache
// (E2E #7/#8, 2026-08-26). 5 minutes bounds that window to one coffee sip.
const CACHE_STATIC = { ttlMs: 300_000, cacheScope: 'private' } as const
const CACHE_SKILLS = { ttlMs: 300_000, cacheScope: 'private' } as const
const CACHE_LIVE = { ttlMs: 0, cacheScope: 'private' } as const

/** Resource templates for any company the key reaches (resources/templates/list, findCompanyScopedResource). */
const COMPANY_CONTEXT_TEMPLATE = 'Accounted://company/{company_id}/context'
const COMPANY_RESOURCE_TEMPLATE = 'Accounted://company/{company_id}/{resource}'

const SERVER_CAPABILITIES = {
  tools: { listChanged: false },
  resources: { listChanged: false },
  prompts: { listChanged: false },
  extensions: {
    // MCP Apps (ratified extension): widgets are served as ui:// resources
    // and referenced from tool _meta.ui.resourceUri (see widgets/).
    'io.modelcontextprotocol/ui': {},
    // MCP Tasks: durable handles for long-running tool calls (see tasks.ts).
    [TASKS_EXTENSION_ID]: {},
  },
}

/**
 * Decode a standard-header value per the 2026-07-28 Value Encoding rules:
 * values outside plain ASCII arrive as =?base64?<data>?= and MUST be decoded
 * before comparing against the request body. Returns null for an absent
 * header so callers can distinguish "not sent" from "sent empty".
 */
function decodeMcpHeaderValue(value: string | null): string | null {
  if (value === null) return null
  const match = /^=\?base64\?(.*)\?=$/.exec(value)
  if (!match) return value
  try {
    return Buffer.from(match[1], 'base64').toString('utf8')
  } catch {
    return value
  }
}

function jsonRpc(id: string | number | null, result: unknown): JsonRpcResponse {
  return { jsonrpc: '2.0', id, result }
}

function jsonRpcError(
  id: string | number | null,
  code: number,
  message: string,
  data?: unknown
): JsonRpcResponse {
  return { jsonrpc: '2.0', id, error: { code, message, data } }
}

/**
 * Schedule a fire-and-forget telemetry emit so it cannot race Vercel function
 * suspension: `after()` keeps the function alive past the JSON-RPC response
 * until the emit settles, which is why event_log inserts used to die with
 * "TypeError: fetch failed". Falls back to a plain fire-and-forget emit when
 * no Next request scope exists (direct handler invocation in tests).
 */
function emitAfterResponse(emit: () => Promise<void>): void {
  try {
    after(emit)
  } catch {
    void emit()
  }
}

/**
 * Emit `mcp.tool_called` telemetry to the event bus. Fire-and-forget: the
 * dispatcher must never block the JSON-RPC response on telemetry, and a failing
 * handler must never surface to the client. The event bus already isolates
 * handlers via Promise.allSettled, but we belt-and-braces here too.
 */
function emitToolCallTelemetry(payload: {
  tool: string
  requiredScope: string | null
  actor: ActorContext
  latencyMs: number
  success: boolean
  isError: boolean
  errorCode: string | null
  errorKind: 'execution' | 'scope_denied' | 'capability_denied' | 'company_access_denied' | 'invalid_arguments' | 'unknown_tool' | 'test_key_write_blocked' | 'unattended_write_blocked' | 'bridge_refused' | 'package_off' | 'rate_limited' | null
  errorMessage: string | null
  /**
   * The specific English diagnostic, passed as `structured.error.message_en`.
   * Stored only when it differs from errorMessage, so the common case where
   * message_sv is already the domain message costs nothing.
   */
  errorDetail?: string | null
  /**
   * Machine vocabulary for the unmapped failures (#2051): errorCauseTag(err),
   * i.e. the SQLSTATE or coded-error code, else the error's class name. For
   * UNKNOWN_ERROR rows message_sv is the constant "Något gick fel. Försök
   * igen.", so without this the residue cannot be clustered at all. Never the
   * raw driver message: that can quote row values from a constraint violation
   * and belongs in the server log, not in event_log.
   */
  errorCause?: string | null
  requestId: string | number | null
  userId: string
  // null/empty while the key's user has no company yet (issue #1814): the
  // event-log persister requires a company scope, so nothing is emitted.
  companyId: string | null
  // How the company was chosen (see lib/events/types.ts). Omitted by the
  // error paths that never reached routing.
  companySelection?: 'default' | 'explicit' | 'operation' | 'scope' | 'none'
}): void {
  if (!payload.companyId) return
  const companyId = payload.companyId
  // Read now, in the message's trace scope: the emit itself runs after the
  // response (emitAfterResponse).
  const traceId = getTraceId() ?? null
  // Its own after-response task, so neither emit can hold up or fail the
  // other. Fixed fields only (posthog-tool-call.ts): no message, no argument.
  emitAfterResponse(() => mirrorToolCallToPostHog({
    tool: payload.tool,
    isError: payload.isError,
    errorCode: payload.errorCode,
    errorKind: payload.errorKind,
    latencyMs: payload.latencyMs,
    client: payload.actor.client,
    sessionId: payload.actor.sessionId,
    serverVersion: SERVER_VERSION,
    userId: payload.userId,
    companyId,
  }))
  emitAfterResponse(() => eventBus
    .emit({
      type: 'mcp.tool_called',
      payload: {
        tool: payload.tool,
        requiredScope: payload.requiredScope,
        ...(payload.companySelection ? { companySelection: payload.companySelection } : {}),
        actorType: payload.actor.type,
        actorId: payload.actor.id ?? null,
        actorLabel: payload.actor.label ?? null,
        latencyMs: payload.latencyMs,
        success: payload.success,
        isError: payload.isError,
        errorCode: payload.errorCode,
        errorKind: payload.errorKind,
        // Truncated: domain error messages are short, but unknown-tool /
        // validation messages can embed long lists. 500 chars is plenty for
        // clustering failures into gotchas without bloating event_log rows.
        errorMessage: payload.errorMessage ? payload.errorMessage.slice(0, 500) : null,
        // Only when it adds something. For most domain failures message_sv IS
        // the specific text and this is null; for the generic registry
        // defaults it is the difference between a usable log and a shrug.
        errorDetail:
          payload.errorDetail && payload.errorDetail !== payload.errorMessage
            ? payload.errorDetail.slice(0, 500)
            : null,
        // Protocol vocabulary only (a SQLSTATE, a code, a class name), capped
        // hard: anything longer is a message pretending to be a tag.
        errorCause: payload.errorCause ? payload.errorCause.slice(0, 64) : null,
        requestId: payload.requestId,
        traceId,
        userId: payload.userId,
        companyId,
        sessionId: payload.actor.sessionId ?? null,
        ...clientTelemetryFields(payload.actor),
      },
    })
    .catch((err) => {
      // Last-resort guard. EventBus.emit already swallows handler failures,
      // but if the bus itself is in a bad state we still don't want to break tools.
      console.error('[mcp] tool_called telemetry emit failed:', err)
    }))
}

